INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('steam', 0, '¿Qué significa la ''A'' en STEAM?', '["Arquitectura","Artes","Astronomía","Algoritmos"]'::jsonb, 1, 'La ''A'' representa Arts (Artes), que incluye diseño, creatividad, música y expresión visual. Sin ella sería solo STEM.', 'exam'),
('steam', 1, '¿Quién propuso añadir la ''A'' a STEM en 2006?', '["Seymour Papert","Georgette Yakman","Mitchel Resnick","John Dewey"]'::jsonb, 1, 'Georgette Yakman argumentó que la innovación real necesita creatividad y diseño, no solo datos técnicos.', 'exam'),
('steam', 2, '¿Cuál es la principal diferencia entre STEM y STEAM?', '["STEAM incluye Artes (creatividad y diseño)","STEM se enfoca más en la práctica y STEAM en la teoría","STEAM agrega Tecnología a las ciencias tradicionales","STEAM está pensado para secundaria y STEM para primaria"]'::jsonb, 0, 'STEAM = STEM + Artes. La ''A'' añade creatividad, diseño y pensamiento estético a las disciplinas técnicas.', 'exam'),
('steam', 3, '¿Cuál NO es una habilidad del siglo XXI que desarrolla STEAM?', '["Pensamiento crítico","Resolución de problemas","Memorización de datos","Comunicación"]'::jsonb, 2, 'STEAM prioriza aplicar el conocimiento. La memorización sola no desarrolla las habilidades que el mundo actual requiere.', 'exam'),
('steam', 4, '¿Qué disciplina STEAM se enfoca en diseñar, construir, probar y mejorar?', '["Ciencia","Tecnología","Ingeniería","Artes"]'::jsonb, 2, 'Ingeniería es el ciclo de creación: diseñar → construir → probar → fallar → rediseñar → mejorar.', 'exam'),
('steam', 5, '¿Cuál es la primera fase del Design Thinking?', '["Idear","Prototipar","Empatizar","Evaluar"]'::jsonb, 2, 'EMPATIZAR es entender al usuario: observar, escuchar, ponerse en sus zapatos. Sin empatía, las soluciones no conectan.', 'exam'),
('steam', 6, '¿Qué metodología activa se basa en indagar, explorar y experimentar sin instrucciones paso a paso?', '["ABP","Design Thinking","Tinkering","Gamificación"]'::jsonb, 2, 'Tinkering (indagar, explorar, experimentar) es aprender tocando y probando. El error es parte del proceso, no un fracaso.', 'exam'),
('steam', 7, '¿Qué herramienta de evaluación es una tabla con criterios y niveles de logro?', '["Examen","Bitácora","Rúbrica","Lista de cotejo simple"]'::jsonb, 2, 'La rúbrica define criterios y niveles (inicio/proceso/logro), dando retroalimentación objetiva y justa al estudiante.', 'exam'),
('steam', 8, 'En un proyecto STEAM, ¿qué se debe evaluar principalmente?', '["El producto final y su presentación ante el público","El proceso completo (incluyendo errores)","Que cada integrante cumpla el rol que se le asignó","Que el producto final funcione a la primera"]'::jsonb, 1, 'En STEAM los errores son aprendizajes. Evaluar solo el producto ignora el proceso de pensamiento más valioso.', 'exam'),
('steam', 9, '¿Qué reto se menciona como una barrera frecuente para STEAM en muchas escuelas de la región?', '["Exceso de contenidos en el currículo","Brecha digital y falta de conectividad","Falta de interés de los estudiantes por la ciencia","Grupos demasiado pequeños para trabajar en equipo"]'::jsonb, 1, 'La brecha digital limita el acceso. Por eso STEAM en contextos con pocos recursos enfatiza proyectos de bajo costo, sin depender de tecnología cara.', 'exam'),
('steam', 10, '¿Cuál es un ejemplo de proyecto STEAM de bajo costo?', '["Kit de robótica con sensores","Semáforo de cartón con colores","Impresora 3D compartida","Simulador en línea en el laboratorio de cómputo"]'::jsonb, 1, 'Un semáforo de cartón integra ciencia, arte, ingeniería y matemáticas sin costo. STEAM no requiere equipos caros.', 'exam'),
('steam', 11, '¿Qué tipo de evaluación se aplica al inicio del proyecto para conocer saberes previos?', '["Sumativa","Formativa","Diagnóstica","Coevaluación"]'::jsonb, 2, 'La evaluación diagnóstica revela lo que los estudiantes ya saben ANTES de enseñar, para partir de ahí.', 'exam'),
('steam', 12, '¿Qué elemento NO pertenece a la gamificación?', '["Puntos acumulables","Niveles","Exámenes sorpresa","Insignias"]'::jsonb, 2, 'Los exámenes sorpresa generan ansiedad. La gamificación usa puntos, niveles e insignias para motivar, no para sorprender negativamente.', 'exam'),
('steam', 13, '¿Cómo se llama el diario donde los estudiantes registran sus avances, errores y reflexiones?', '["Bitácora","Portafolio de evidencias","Rúbrica de proceso","Mapa del proyecto"]'::jsonb, 0, 'La bitácora de aprendizaje documenta el proceso: qué intenté, qué falló, qué descubrí. Es metacognición en acción.', 'exam'),
('steam', 14, '¿Qué porcentaje de aprobación se necesita para obtener el certificado?', '["65%","60%","70%","80%"]'::jsonb, 2, 'El 70% es el umbral de aprobación. Significa dominar al menos 14 de 20 preguntas del examen.', 'exam'),
('steam', 15, '¿Qué disciplina STEAM se relaciona con identificar problemas del entorno y crear soluciones con valor?', '["Emprendimiento","Artes","Matemáticas","Ciencia"]'::jsonb, 0, 'Entrepreneurship (Emprendimiento) no es solo vender: es tener iniciativa para resolver problemas con impacto real.', 'exam'),
('steam', 16, '¿Cuál es un ejemplo de tecnología análoga válida en STEAM?', '["Un simulador digital del fenómeno","Un sistema de banderas para comunicarse","Una tableta con aplicaciones educativas instaladas","Un video explicativo proyectado"]'::jsonb, 1, 'Tecnología es cualquier herramienta que extiende nuestra capacidad. Un sistema de banderas es tecnología de comunicación.', 'exam'),
('steam', 17, 'En la rúbrica de ejemplo, ¿cuántos puntos máximos puede obtener un proyecto?', '["10","20","50","100"]'::jsonb, 1, 'La rúbrica del curso tiene 5 criterios × 4 puntos máximo cada uno = 20 puntos totales posibles.', 'exam'),
('steam', 18, '¿Qué acción ayuda a romper estereotipos de género en STEAM?', '["Dejar que cada estudiante elija su rol sin intervenir","Mostrar ejemplos de mujeres inventoras","Dar a las niñas tareas de diseño y a los niños de construcción","Hablar del tema solo si algún estudiante lo menciona"]'::jsonb, 1, 'Mostrar referentes femeninos en ciencia e ingeniería demuestra que STEAM no tiene género. Todos pueden innovar.', 'exam'),
('steam', 19, '¿Cuál es el objetivo final de STEAM según el curso?', '["Que cada escuela tenga un laboratorio de robótica con equipo moderno","Preparar estudiantes para resolver problemas reales con creatividad","Mejorar los resultados en pruebas estandarizadas de ciencias","Formar más estudiantes que elijan carreras de ingeniería"]'::jsonb, 1, 'STEAM prepara para un futuro incierto: trabajos que no existen, problemas que no conocemos, herramientas que aún no se inventan.', 'exam'),
('steam', 20, '¿Qué hace un docente STEAM frente al error de un estudiante?', '["Lo penaliza con una nota baja","Lo deja pasar para no frenar el ritmo del grupo","Lo convierte en oportunidad de aprendizaje","Lo corrige de inmediato para que no se fije el error"]'::jsonb, 2, 'En STEAM el error es datos, no fracaso. ''¿Qué aprendiste de lo que no funcionó?'' es la pregunta correcta.', 'exam'),
('steam', 21, 'Un estudiante diseña una maqueta de acueducto para su comunidad, mide las tuberías, investiga cómo fluye el agua y decora el modelo para presentarlo. ¿Qué disciplinas STEAM está integrando?', '["Ingeniería y Matemáticas, porque el Arte es solo la decoración","Ciencia e Ingeniería; medir es parte de la ingeniería","Ciencia, Ingeniería, Matemáticas y Arte","Ingeniería, Tecnología y Matemáticas, sin Ciencia"]'::jsonb, 2, 'Investiga el agua (Ciencia), diseña y construye (Ingeniería), mide las tuberías (Matemáticas) y decora para presentar (Arte). Un solo proyecto, cuatro disciplinas integradas.', 'exam'),
('steam', 22, '¿Qué es ABP (Aprendizaje Basado en Proyectos)?', '["Una serie de ejercicios del libro que los estudiantes resuelven en equipo","Un enfoque donde los estudiantes resuelven un problema real creando algo","Un trabajo de investigación individual que se presenta al final del periodo","Trabajo en equipos donde cada uno hace una parte del tema asignado por el docente"]'::jsonb, 1, 'ABP tiene un producto final con impacto real. No es un ejercicio, es un proyecto con significado para la comunidad.', 'exam'),
('steam', 23, '¿Cuál de estas NO es una fase del Design Thinking?', '["Definir","Memorizar","Prototipar","Idear"]'::jsonb, 1, 'Las 5 fases son: Empatizar → Definir → Idear → Prototipar → Evaluar. Memorizar no es parte del proceso creativo.', 'exam'),
('steam', 24, '¿Qué tipo de evaluación acompaña el proceso durante el proyecto?', '["Diagnóstica","Formativa","Sumativa","Coevaluación final"]'::jsonb, 1, 'La evaluación FORMATIVA ocurre DURANTE el proceso. Retroalimenta y permite ajustar antes de que sea demasiado tarde.', 'exam'),
('steam', 25, '¿Por qué STEAM integra las disciplinas en lugar de enseñarlas por separado?', '["Porque así se cubren más contenidos en menos tiempo","Porque los problemas reales son multidisciplinarios","Porque los estudiantes aprenden mejor una materia a la vez","Para que cada docente pueda especializarse en su área"]'::jsonb, 1, 'Los problemas reales—cambio climático, salud, movilidad—no son solo de ciencia o solo de arte. Requieren todo a la vez.', 'exam'),
('steam', 26, 'En un proyecto STEAM, un estudiante usa cartón para construir su solución mientras otro agrega sensores electrónicos a la misma. Ambos trabajan en el mismo reto. ¿Qué característica del ABP demuestra esto?', '["Que cada estudiante debe resolver el reto a su manera, sin equipo","Que el proyecto permite distintos niveles de profundidad según cada estudiante","Que no hay una respuesta correcta y todo vale igual","Que el material usado determina qué tan bien se evalúa"]'::jsonb, 1, 'Un buen proyecto STEAM permite que cada estudiante participe desde su nivel actual y llegue tan lejos como pueda. No excluye a nadie ni limita a los más avanzados.', 'exam'),
('steam', 27, '¿Cuál es el rol del docente en un aula STEAM?', '["Explicar cada disciplina por separado antes del proyecto","Diseñar experiencias y guiar el aprendizaje","Asignar los roles y revisar que cada uno cumpla su parte","Preparar el material y dar los pasos a seguir"]'::jsonb, 1, 'El docente STEAM pasa de ''sabio en el escenario'' a ''guía en el lado''. Diseña contextos donde el estudiante construye.', 'exam'),
('steam', 28, '¿Cómo se conecta la matemática con los otros componentes STEAM?', '["Se trabaja aparte y luego se aplica en el proyecto","Es el lenguaje de medición de las otras disciplinas","Se usa sobre todo en el componente de ingeniería","Sirve para calcular la nota final del proyecto"]'::jsonb, 1, 'Matemática es el lenguaje de STEAM: mide, calcula, modela y predice para ciencia, ingeniería, tecnología y emprendimiento.', 'exam'),
('steam', 29, '¿Qué es la metacognición y por qué importa en STEAM?', '["Recordar lo aprendido en proyectos anteriores","Pensar sobre cómo aprendemos y mejorar nuestro propio proceso","Pensar en voz alta mientras se resuelve un problema","Evaluar el trabajo de los compañeros"]'::jsonb, 1, 'Metacognición = pensar sobre el propio pensamiento. En STEAM los estudiantes reflexionan qué funcionó y qué cambiarían.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('abp', 0, '¿Cuál es la característica que distingue el ABP de un trabajo grupal convencional?', '["El trabajo en equipo con roles definidos","Un problema auténtico y complejo como punto de partida","El uso de varias materias a la vez","La presentación final ante el grupo"]'::jsonb, 1, 'El ABP se define por la autenticidad del problema, no por el formato grupal.', 'exam'),
('abp', 1, '¿Cuál es la primera fase del ciclo ABP?', '["La investigación de la información","La formación de los equipos y sus roles","El lanzamiento con la Pregunta Guía","La planificación del producto"]'::jsonb, 2, 'El lanzamiento con la Pregunta Guía es el punto de partida que genera curiosidad y compromiso.', 'exam'),
('abp', 2, '¿Qué hace que una Pregunta Guía sea efectiva en ABP?', '["Que tenga una respuesta clara que los estudiantes puedan verificar","Que sea abierta, conectada a la realidad y provoque curiosidad","Que cubra todos los contenidos de la unidad","Que sea lo bastante concreta para responderla en pocas clases"]'::jsonb, 1, 'Una buena Pregunta Guía no tiene respuesta única, es relevante y genera deseo de investigar.', 'exam'),
('abp', 3, '¿En qué fase los estudiantes definen qué harán y cómo lo harán?', '["Investigación","Reflexión","Diseño","Presentación"]'::jsonb, 2, 'La fase de diseño es donde los equipos planifican su solución, crean bocetos y asignan roles.', 'exam'),
('abp', 4, '¿Por qué la audiencia real es importante en el ABP?', '["Porque permite evaluar con otros criterios además de los del docente","Porque eleva la calidad del trabajo y autentica el propósito del aprendizaje","Porque permite que el docente delegue la calificación del proyecto en personas externas","Porque las familias valoran ver el trabajo de sus hijos"]'::jsonb, 1, 'La audiencia real transforma la motivación: los estudiantes trabajan para impactar personas reales, no para sacar una nota.', 'exam'),
('abp', 5, '¿Cuál es el rol del docente durante la fase de creación del proyecto?', '["Dar instrucciones detalladas paso a paso","Observar, hacer preguntas, documentar y apoyar cuando sea necesario","Calificar el avance de cada equipo y corregir los errores antes de que los cometan","Hacer el trabajo junto a los estudiantes"]'::jsonb, 1, 'El docente circula, observa, hace preguntas guía y apoya estratégicamente sin quitar la agencia a los estudiantes.', 'exam'),
('abp', 6, '¿Qué son las mini-lecciones en el contexto del ABP?', '["Exámenes cortos durante el proyecto","Explicaciones breves de lo que los equipos necesitan justo en ese momento","Actividades de calentamiento","Explicaciones largas al inicio del proyecto para cubrir todo el contenido antes de empezar"]'::jsonb, 1, 'Las mini-lecciones just-in-time enseñan el contenido cuando los estudiantes lo necesitan para avanzar en su proyecto.', 'exam'),
('abp', 7, '¿Qué porcentaje del total debería representar la evaluación del PROCESO en ABP?', '["Alrededor de 10%, porque el producto es lo que muestra lo aprendido","Un porcentaje significativo, típicamente 30-50%","100%, porque lo que importa en ABP es el proceso","No se evalúa: el proceso se observa pero no se califica"]'::jsonb, 1, 'El proceso merece un peso significativo porque es donde ocurre la mayor parte del aprendizaje y el desarrollo de competencias.', 'exam'),
('abp', 8, '¿Qué es la Lista de Necesidades de Aprendizaje (LNA)?', '["Una lista de materiales para el proyecto","Lo que los estudiantes identifican que necesitan saber para responder la Pregunta Guía","La lista de contenidos del currículo que el docente debe cubrir antes de iniciar el proyecto","Los libros que el docente recomienda"]'::jsonb, 1, 'La LNA convierte a los estudiantes en dueños de su aprendizaje al identificar sus propios vacíos de conocimiento.', 'exam'),
('abp', 9, '¿Cuándo deben conocer los estudiantes los criterios de evaluación del proyecto?', '["Al final, para no condicionar su creatividad","Al inicio, antes de comenzar a trabajar","A la mitad del proyecto, cuando ya tienen una idea clara","Cuando entregan, para que puedan autoevaluarse"]'::jsonb, 1, 'Los criterios deben conocerse desde el inicio para que sirvan como guía de calidad durante todo el proceso.', 'exam'),
('abp', 10, '¿Cómo puede el ABP implementarse exitosamente en una escuela rural sin internet?', '["Adaptándolo a proyectos cortos de investigación en el libro de texto","Usando la comunidad como recurso: ancianos, artesanos, entornos naturales","Usando materiales impresos que el docente trae preparados","Trayendo materiales comprados de la ciudad y dejando la comunidad fuera del proyecto"]'::jsonb, 1, 'La comunidad es el recurso más auténtico del ABP. Las escuelas sin tecnología a menudo producen proyectos más genuinos.', 'exam'),
('abp', 11, '¿Qué herramienta resume todos los elementos de un proyecto antes de comenzar?', '["La rúbrica","El diario del proyecto","El Mapa del Proyecto","La Lista de Necesidades de Aprendizaje"]'::jsonb, 2, 'El Mapa del Proyecto responde: problema, pregunta guía, producto, audiencia, contenidos, duración, recursos y evaluación.', 'exam'),
('abp', 12, '¿Cuál es la fase final del ciclo ABP?', '["La presentación ante la audiencia","La reflexión","La evaluación sumativa del producto","La entrega del producto final"]'::jsonb, 1, 'La reflexión es la última fase y la que consolida el aprendizaje. Sin reflexión, el proyecto fue solo una actividad.', 'exam'),
('abp', 13, 'En un proyecto ABP, ¿qué deben hacer los equipos cuando encuentran un obstáculo durante la creación?', '["Pedir al docente que les indique la solución correcta para no perder tiempo del proyecto","Identificar qué necesitan aprender, ajustar su plan y seguir avanzando","Cambiar a una idea más sencilla que puedan terminar a tiempo","Esperar al siguiente punto de revisión para consultarlo"]'::jsonb, 1, 'Encontrar y superar obstáculos es parte del aprendizaje en ABP. El docente apoya con preguntas, no con respuestas.', 'exam'),
('abp', 14, 'Un proyecto ABP exitoso en un contexto intercultural debería:', '["Incorporar tecnología actual para que el proyecto sea moderno","Conectar con problemas reales de la comunidad e incorporar saberes locales y culturales","Seguir un modelo probado en otros países, adaptando solo el idioma","Evitar temas culturales para no generar controversia"]'::jsonb, 1, 'El ABP es más poderoso cuando incorpora la riqueza cultural, lingüística y comunitaria del contexto local.', 'exam'),
('abp', 15, '¿Qué diferencia a los puntos de revisión de una evaluación sumativa?', '["Los puntos de revisión los hace el docente; la sumativa, los estudiantes","Ocurren durante el proceso y sirven para mejorar, no para la nota final","Los puntos de revisión son más exigentes porque detectan errores","Ambos cuentan para la nota, solo cambia el momento del proyecto"]'::jsonb, 1, 'Los puntos de revisión son formativos: sirven para retroalimentar y mejorar mientras aún hay tiempo de hacerlo.', 'exam'),
('abp', 16, '¿Qué es la coevaluación?', '["El docente y el estudiante evalúan juntos el trabajo","Los estudiantes evalúan el trabajo de sus compañeros usando criterios acordados","Una evaluación grupal donde todos reciben la misma nota","El estudiante evalúa su propio trabajo con una rúbrica"]'::jsonb, 1, 'La coevaluación desarrolla pensamiento crítico y capacidad de dar retroalimentación constructiva, habilidades valiosas para la vida.', 'exam'),
('abp', 17, '¿Cómo se conecta el ABP con el currículo nacional?', '["El ABP trabaja habilidades blandas y el currículo se cubre aparte","Un solo proyecto puede cubrir competencias de varias áreas del currículo a la vez","El ABP reemplaza el currículo durante el tiempo del proyecto","Se conecta sobre todo con Ciencias, por el método científico"]'::jsonb, 1, 'Un proyecto bien diseñado integra competencias de matemática, comunicación, ciencias y formación ciudadana del currículo al mismo tiempo.', 'exam'),
('abp', 18, '¿Qué debe hacer el docente si un equipo tiene una idea que cree que no funcionará?', '["Sugerirles con tacto una idea que sí funcione","Dejarles probar con apoyo de preguntas guía, y aprender del intento","Pedirles que justifiquen por escrito antes de seguir","Darles los pasos detallados para que no se pierdan"]'::jsonb, 1, 'El fracaso controlado es parte del aprendizaje en ABP. Los estudiantes que prueban, fallan y ajustan aprenden más que los que solo ejecutan instrucciones.', 'exam'),
('abp', 19, '¿Cuál es el indicador más claro de que un proyecto ABP fue exitoso?', '["La mayoría de los estudiantes obtuvo una calificación alta en el producto","Los estudiantes pueden explicar qué aprendieron, por qué importa y cómo lo usarían en otro contexto","El producto final fue bien recibido por la audiencia","Que el proyecto terminó a tiempo y todos los equipos entregaron su producto completo"]'::jsonb, 1, 'El éxito en ABP se mide por la transferencia del aprendizaje: los estudiantes pueden aplicar lo que aprendieron más allá del proyecto específico.', 'exam'),
('abp', 20, '¿Por qué la reflexión es indispensable en el ABP?', '["Para dejar registro del proyecto ante la dirección","Porque transforma la experiencia en aprendizaje duradero y desarrolla metacognición","Para que el docente obtenga notas de participación individual","Es útil, pero se puede omitir si falta tiempo al final"]'::jsonb, 1, 'Sin reflexión, el cerebro no consolida el aprendizaje. La reflexión es donde los estudiantes procesan qué aprendieron y cómo pueden mejorarlo.', 'exam'),
('abp', 21, '¿Cómo puede el ABP fortalecer la identidad cultural en comunidades con lengua y cultura originarias?', '["Traduciendo al final el producto a la lengua originaria","Incorporando lenguas maternas, saberes ancestrales y expertos locales como parte del proceso de investigación","Trabajando en la lengua dominante para que dominen el idioma oficial","Tratando los temas culturales en una asignatura aparte"]'::jsonb, 1, 'El ABP otorga valor académico real al conocimiento en lenguas maternas y saberes ancestrales, fortaleciendo la identidad cultural.', 'exam'),
('abp', 22, '¿Cuál es el tamaño ideal de un equipo en ABP?', '["Parejas (2 estudiantes)","3-4 estudiantes","Grupos de 5-6","Depende solo del número de estudiantes del aula"]'::jsonb, 1, 'Equipos de 3-4 permiten división de roles, diversidad de perspectivas y comunicación manejable sin que nadie se pierda.', 'exam'),
('abp', 23, '¿Qué información debe incluir el Mapa del Proyecto?', '["El nombre del proyecto, el calendario y los equipos","Problema, pregunta guía, producto, audiencia, contenidos y evaluación","La lista de materiales, el calendario de entregas y la rúbrica del producto","Los nombres de los estudiantes, sus roles y las fechas de revisión"]'::jsonb, 1, 'El Mapa del Proyecto es el documento de planificación completo que responde todos los "qué, quién, cuándo y para qué" del proyecto.', 'exam'),
('abp', 24, 'Un docente hace ABP por primera vez. ¿Cuál es el mejor consejo?', '["Diseñar el proyecto más ambicioso posible para motivar a los estudiantes","Comenzar con un proyecto pequeño y manejable, documentar los resultados y aprender de la experiencia","Esperar a recibir capacitación completa antes de intentarlo","Tomar un proyecto exitoso de otra escuela y aplicarlo tal cual"]'::jsonb, 1, 'Un proyecto modesto que se completa y se documenta enseña más que un proyecto ambicioso que se abandona. La experiencia es el mejor maestro en ABP.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('design-thinking', 0, '¿Cuál es el principio fundamental del Design Thinking?', '["Usar la creatividad para generar muchas soluciones","Partir de la empatía con las personas que viven el problema","Encontrar la solución más lógica y eficiente","Seguir las fases en orden para no saltarse pasos"]'::jsonb, 1, 'La empatía es el corazón del DT. Sin entender genuinamente a las personas, cualquier solución es una suposición.', 'exam'),
('design-thinking', 1, '¿Cuáles son las 5 fases del Design Thinking en orden?', '["Investigar, Definir, Diseñar, Construir, Evaluar","Empatizar, Definir, Idear, Prototipar, Evaluar","Empatizar, Idear, Definir, Prototipar, Evaluar","Definir, Empatizar, Idear, Prototipar, Evaluar"]'::jsonb, 1, 'Empatizar → Definir → Idear → Prototipar → Evaluar son las 5 fases del DT, aunque se pueden recorrer de manera no lineal.', 'exam'),
('design-thinking', 2, '¿Qué herramienta organiza los hallazgos de la empatía en 4 cuadrantes (Dice, Hace, Piensa, Siente)?', '["El mapa de actores","El Mapa de Empatía","El Mapa del Proyecto","La matriz FODA"]'::jsonb, 1, 'El Mapa de Empatía organiza los datos de la investigación de empatía para revelar patrones y necesidades profundas.', 'exam'),
('design-thinking', 3, '¿Cuál es el formato correcto del enunciado del problema en Design Thinking?', '["El problema es que los estudiantes no participan","[Persona] necesita [necesidad] porque [insight]","¿Cómo podríamos [solución]?","[Persona] necesita [solución] para [objetivo]"]'::jsonb, 1, 'El formato [Persona] necesita [necesidad] porque [insight] centra la perspectiva en las personas y abre posibilidades de solución.', 'exam'),
('design-thinking', 4, '¿Cuál es la regla más importante durante la fase de ideación?', '["Proponer ideas que sean viables con los recursos disponibles","Aplazar el juicio y priorizar la cantidad","Que el docente elija las ideas que se van a desarrollar","Discutir cada idea en el momento para mejorarla"]'::jsonb, 1, 'Aplazar el juicio durante la ideación permite que emerjan ideas creativas que de otro modo serían silenciadas prematuramente.', 'exam'),
('design-thinking', 5, '¿Qué es un prototipo en el contexto del Design Thinking?', '["Una primera versión bien terminada para mostrar a los usuarios","Una versión rápida y barata de una idea","Un modelo a escala exacta del producto final","Un dibujo detallado de la solución antes de construirla"]'::jsonb, 1, 'Un prototipo es para aprender, no para impresionar. Debe ser rápido, barato y descartable si es necesario.', 'exam'),
('design-thinking', 6, 'Después de probar un prototipo que no funcionó como esperabas, ¿qué haces?', '["Descartar la idea y pasar a la segunda más votada","Extraer el aprendizaje específico del fracaso y usarlo para mejorar la siguiente versión","Seguir con el mismo prototipo un tiempo más para ver si mejora","Volver al inicio del proceso y entrevistar de nuevo a todos"]'::jsonb, 1, 'En DT, el fracaso es información valiosa. Lo que no funcionó te dice exactamente qué mejorar en la siguiente iteración.', 'exam'),
('design-thinking', 7, '¿Por qué el DT no necesita ser lineal?', '["Porque cada fase se puede hacer en paralelo con las demás","Porque responde a lo que descubres; a veces hay que volver a empatizar o redefinir","Porque algunas fases pueden omitirse si el equipo ya conoce bien el problema de antemano","Porque el orden depende de la experiencia del facilitador"]'::jsonb, 1, 'El DT es iterativo: cada ciclo aporta aprendizaje que puede llevarte a ajustar cualquier fase anterior. La flexibilidad es una fortaleza, no una debilidad.', 'exam'),
('design-thinking', 8, '¿Qué diferencia una entrevista de empatía de una encuesta?', '["La entrevista permite recoger datos de más personas en menos tiempo","La entrevista busca comprender la experiencia y los sentimientos, no datos numéricos; usa preguntas abiertas y escucha activa","La encuesta es más confiable porque evita la subjetividad","La entrevista es una encuesta hecha de forma oral"]'::jsonb, 1, 'La empatía requiere historias y profundidad, no estadísticas. La entrevista de empatía es conversacional y centrada en la experiencia subjetiva.', 'exam'),
('design-thinking', 9, '¿Qué debe hacer el facilitador si alguien critica una idea durante la ideación?', '["Aceptar la crítica porque el grupo necesita ser realista","Recordar la regla de no juzgar y pedir que todas las ideas se registren primero","Pedir que se descarte la idea si la mayoría está de acuerdo","Debatir la viabilidad de la idea en ese momento"]'::jsonb, 1, 'Durante la ideación, todas las ideas tienen valor. El juicio llega después, en la fase de selección de ideas.', 'exam'),
('design-thinking', 10, '¿Cómo se adapta el DT para niños de primaria baja?', '["Se aplica igual que con adultos, pero con más tiempo","Con apoyos visuales y concretos, problemas cercanos y un proceso simplificado","Se usan solo las fases de idear y prototipar","Se reserva para cuando ya saben leer y escribir con fluidez, porque requiere registrar ideas"]'::jsonb, 1, 'Con niños pequeños el DT se hace visual, físico y con problemas concretos cercanos. La curiosidad y empatía infantil son recursos naturales.', 'exam'),
('design-thinking', 11, '¿Qué es el Crazy 8s?', '["Una técnica de evaluación donde se califican 8 prototipos en 8 minutos con una rúbrica","Una técnica para generar 8 ideas distintas en 8 minutos, dibujándolas","Un método para seleccionar la mejor idea entre ocho","Una dinámica de empatía en ocho pasos"]'::jsonb, 1, 'Crazy 8s usa la velocidad (1 minuto por idea) para forzar la creatividad. La presión de tiempo impide la autocrítica y genera variedad.', 'exam'),
('design-thinking', 12, 'Al implementar DT en comunidades indígenas, ¿cuál es el primer paso?', '["Iniciar las entrevistas con las familias para no perder tiempo","Consultar con las autoridades y líderes comunitarios para entender el protocolo cultural","Hacer las entrevistas en español para que todos se entiendan","Aplicar el proceso igual que en otras escuelas, para comparar"]'::jsonb, 1, 'El respeto a los protocolos comunitarios es empatía en acción. Sin la validación comunitaria, el DT se convierte en extractivismo de conocimiento.', 'exam'),
('design-thinking', 13, '¿Cuál es la técnica de los 5 Porqués?', '["Hacer cinco preguntas abiertas en cada entrevista de empatía","Preguntar \"por qué\" sucesivamente para llegar a la causa raíz de un problema","Revisar una idea con cinco criterios antes de prototiparla","Pedir a cinco personas su opinión sobre el problema"]'::jsonb, 1, 'Preguntar "¿por qué?" sucesivamente revela las causas profundas de los problemas, evitando soluciones superficiales que no resuelven la raíz.', 'exam'),
('design-thinking', 14, '¿Qué es el brainwriting?', '["Escribir un resumen individual de las entrevistas","Cada uno escribe ideas en silencio y pasa la hoja para que otros las amplíen","Una lluvia de ideas en voz alta donde gana la persona que propone más ideas en menos tiempo","Escribir en silencio las críticas a cada prototipo"]'::jsonb, 1, 'El brainwriting es más equitativo que el brainstorming oral porque todos participan simultáneamente y en silencio, evitando que los más extrovertidos dominen.', 'exam'),
('design-thinking', 15, '¿Por qué es importante que el enunciado del problema NO implique ya la solución?', '["Para que el proceso dure lo suficiente y se viva cada fase","Para mantener abierto el espacio de soluciones posibles y no llegar sesgados a la ideación","Porque la solución la debe proponer el docente","Para que el enunciado sea más corto y fácil de recordar"]'::jsonb, 1, 'Un enunciado que ya implica la solución cierra el espacio creativo. "Necesitamos tabletas" no es un problema, es ya una solución no verificada.', 'exam'),
('design-thinking', 16, '¿Qué beneficio tiene usar DT en equipos de docentes?', '["Reduce el trabajo individual de cada docente","La diversidad de perspectivas enriquece la empatía e ideación, y el apoyo mutuo facilita la implementación","Permite que la dirección supervise mejor cada proyecto","Cada docente trabaja su parte y luego se suman los resultados"]'::jsonb, 1, 'Los equipos de docentes tienen perspectivas complementarias sobre los mismos estudiantes. Esa diversidad produce insights y soluciones más ricas.', 'exam'),
('design-thinking', 17, '¿Cuál es el indicador de que la fase de empatía fue exitosa?', '["Se entrevistó a muchas personas distintas","Se descubrieron necesidades o insights que no eran evidentes al inicio","Se confirmaron las hipótesis que el equipo tenía al inicio","Todos los entrevistados coincidieron en el problema"]'::jsonb, 1, 'La empatía exitosa revela lo no evidente: contradicciones, necesidades implícitas, patrones ocultos que cambian la comprensión del problema.', 'exam'),
('design-thinking', 18, 'Una docente usa DT para entender por qué los niños no leen. Después de entrevistar a 6 niños, descubre que la mayoría siente vergüenza de leer en voz alta. ¿Cuál es el próximo paso?', '["Comprar más libros atractivos para la biblioteca del aula","Formular un enunciado del problema centrado en la vergüenza y generar ideas que aborden esa necesidad emocional","Aplicar de inmediato una solución que funcionó en otra escuela, sin volver a revisar lo descubierto en las entrevistas","Informar a las familias para que practiquen la lectura en voz alta en casa"]'::jsonb, 1, 'El insight (vergüenza de leer) es la base del enunciado del problema. Las soluciones deben abordar esa barrera emocional, no el síntoma superficial.', 'exam'),
('design-thinking', 19, '¿Cuál es la diferencia entre empatía y compasión en el contexto del DT?', '["Son lo mismo: ambas buscan sentir lo que siente el otro","La compasión es sentir lástima; la empatía es curiosidad activa por entender la experiencia del otro para diseñar mejores soluciones","La compasión es más útil en DT porque motiva a actuar","La empatía es analizar datos del usuario; la compasión, escucharlo"]'::jsonb, 1, 'La empatía del DT va más allá de la lástima: es investigación activa de la experiencia subjetiva del otro para informar el diseño de soluciones efectivas.', 'exam'),
('design-thinking', 20, 'Un equipo generó 25 ideas y debe elegir. Cada integrante reparte 3 marcas entre sus favoritas. ¿Qué método de selección usan?', '["Votación de puntos","Matriz de impacto/esfuerzo","Crazy 8s","Mapa de empatía"]'::jsonb, 0, 'La votación de puntos permite priorizar rápido. Las ideas no elegidas se guardan para futuros proyectos.', 'exam'),
('design-thinking', 21, 'En la fase de evaluar del DT, ¿qué se busca con el prototipo?', '["Decidir si el equipo aprueba o reprueba, según si el prototipo funcionó a la primera","Aprender qué funcionó, qué no y qué cambiar en la próxima versión","Presentar el producto final a la dirección","Calificar a cada integrante del equipo"]'::jsonb, 1, 'Evaluar no es aprobar o reprobar: es aprender del prototipo, idealmente con las personas para quienes se diseña.', 'exam'),
('design-thinking', 22, 'Al probar el prototipo, el equipo descubre que no entendía bien el problema de los estudiantes. ¿A qué fase conviene volver?', '["A Prototipar, para mejorar los detalles de la versión actual","A Empatizar","A Evaluar otra vez, con un grupo distinto de estudiantes","A Idear, para votar otra vez las mismas ideas"]'::jsonb, 1, 'El ciclo de iteración regresa al punto que indica el aprendizaje: si el problema no se entendía, se vuelve a empatizar.', 'exam'),
('design-thinking', 23, 'Una escuela sin internet quiere aplicar DT. ¿Qué materiales necesita?', '["Una suscripción a herramientas digitales colaborativas, como pizarras en línea","Papel, tarjetas, marcadores de colores y una pared para organizar ideas","Tabletas o computadoras para registrar las entrevistas","Un software de diseño para crear los prototipos"]'::jsonb, 1, 'Cada herramienta digital tiene su versión en papel: post-its, papel bond en la pared, cuaderno de proyecto.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('evaluacion', 0, '¿Qué es la evaluación auténtica?', '["Un examen con preguntas de aplicación en vez de memoria","Tareas significativas, parecidas a situaciones reales, que muestran lo aprendido","La evaluación que hacen evaluadores externos a la escuela","Una evaluación tipo examen con preguntas tomadas del libro, aplicada al final para comprobar lo memorizado"]'::jsonb, 1, 'La evaluación auténtica tiene propósito real, audiencia más allá del docente y requiere aplicar conocimiento, no solo recordarlo.', 'exam'),
('evaluacion', 1, '¿Cuáles son los tres tipos de evaluación y en qué momento se aplica cada uno?', '["Inicial, parcial y final, según el calendario escolar","Diagnóstica (al inicio), formativa (durante) y sumativa (al final)","Oral, escrita y práctica, según el tipo de contenido","Individual, grupal y de proyecto, según el tema"]'::jsonb, 1, 'Diagnóstica al inicio (¿qué saben?), formativa durante el proceso (¿cómo van?) y sumativa al final (¿qué lograron?) forman el sistema completo de evaluación.', 'exam'),
('evaluacion', 2, '¿Por qué la evaluación formativa es la más poderosa pedagógicamente?', '["Porque permite asignar notas con mayor frecuencia","Porque ocurre durante el proceso y permite corregir el rumbo cuando aún hay tiempo","Porque es la que más peso tiene en la nota final y por eso los estudiantes se esfuerzan más","Porque reduce la ansiedad ante los exámenes finales"]'::jsonb, 1, 'La evaluación formativa retroalimenta cuando aún se puede mejorar. La sumativa solo constata lo que ya ocurrió.', 'exam'),
('evaluacion', 3, '¿Qué es una rúbrica?', '["Una lista de cotejo con lo que debe tener el trabajo","Una tabla que describe niveles de desempeño para distintos criterios de evaluación","Una escala numérica para asignar la nota final","Un formato para registrar la observación diaria"]'::jsonb, 1, 'La rúbrica es el mapa de calidad: describe qué se ve en distintos niveles de desempeño para cada criterio evaluado.', 'exam'),
('evaluacion', 4, '¿Cuándo deben conocer los estudiantes la rúbrica?', '["Al recibir el trabajo calificado, para que entiendan la nota","Antes de comenzar el trabajo que será evaluado","A la mitad del proceso, para que no se limiten al inicio","Solo cuando la piden, para no condicionar su trabajo"]'::jsonb, 1, 'La rúbrica es un mapa de destino, no un veredicto. Compartirla al inicio permite que los estudiantes apunten a la calidad desde el comienzo.', 'exam'),
('evaluacion', 5, '¿Cuál es la diferencia entre la rúbrica holística y la analítica?', '["La holística evalúa cada criterio por separado; la analítica da una sola nota al trabajo en conjunto","La holística evalúa el trabajo en conjunto; la analítica evalúa cada criterio por separado","La analítica se usa para proyectos y la holística para exámenes","La holística es más precisa porque considera más criterios"]'::jsonb, 1, 'La rúbrica analítica da retroalimentación específica por dimensión. La holística es más rápida pero menos útil para orientar mejoras.', 'exam'),
('evaluacion', 6, '¿Qué hace diferente a un portafolio de aprendizaje de simplemente guardar trabajos?', '["Que se organiza por fecha y por asignatura","La selección deliberada y la reflexión del estudiante sobre su avance","Que el docente elige los mejores trabajos del estudiante y los organiza por fecha y por materia","Que incluye solo los trabajos con mejor nota del periodo"]'::jsonb, 1, 'La selección con propósito y la reflexión del estudiante son lo que convierte una carpeta en un portafolio de aprendizaje.', 'exam'),
('evaluacion', 7, '¿Qué es la tarjeta de reflexión en un portafolio?', '["Una autoevaluación numérica del estudiante","Una nota del estudiante explicando por qué eligió cada pieza y qué aprendió","Una nota del docente explicando qué calificación recibió cada pieza y en qué falló el estudiante","El índice con los trabajos incluidos"]'::jsonb, 1, 'La tarjeta de reflexión es el elemento metacognitivo del portafolio. El estudiante explica su selección y su proceso de aprendizaje.', 'exam'),
('evaluacion', 8, '¿Qué son las conferencias de portafolio lideradas por el estudiante?', '["Exámenes orales donde el estudiante defiende frente al docente cada trabajo de su portafolio","Reuniones donde el estudiante presenta a su familia lo que aprendió","Presentaciones del portafolio ante la dirección y otros docentes","Sesiones donde el estudiante explica su portafolio a sus compañeros"]'::jsonb, 1, 'Las Student-Led Conferences invierten la relación tradicional: el estudiante comunica su aprendizaje a los padres, desarrollando responsabilidad y comunicación.', 'exam'),
('evaluacion', 9, '¿Cuál es el principal beneficio de la autoevaluación?', '["Le ahorra tiempo de corrección al docente","Desarrolla metacognición y responsabilidad del estudiante sobre su propio aprendizaje","Reemplaza la calificación del docente en las tareas","Hace que los estudiantes acepten mejor su nota final"]'::jsonb, 1, 'La metacognición (pensar sobre el propio aprendizaje) es una habilidad fundamental para el aprendizaje autónomo de por vida.', 'exam'),
('evaluacion', 10, '¿Qué es el "ticket de salida"?', '["Una pregunta de repaso al inicio de la siguiente clase","Una reflexión breve al cierre donde el estudiante anota qué aprendió y qué duda","Un examen corto de 10 preguntas al final de la semana para obtener una nota adicional en el periodo","Una tarea breve para la casa sobre el tema del día"]'::jsonb, 1, 'El ticket de salida es evaluación formativa simple y efectiva: da información sobre el estado de comprensión de cada estudiante en 3 minutos.', 'exam'),
('evaluacion', 11, '¿Qué es la coevaluación?', '["El docente evalúa dos veces el mismo trabajo","Los estudiantes evalúan el trabajo de sus compañeros usando criterios acordados","Una evaluación grupal donde todos reciben la misma nota","Un examen hecho en colaboración"]'::jsonb, 1, 'La coevaluación desarrolla pensamiento crítico y la capacidad de dar retroalimentación constructiva, habilidades valiosas para la vida.', 'exam'),
('evaluacion', 12, '¿Por qué es importante "calibrar" a los estudiantes antes de hacer coevaluación?', '["Para que el proceso sea más rápido","Para que aprendan a aplicar los criterios de manera consistente y no evalúen solo por amistad","Para que evalúen exactamente igual que el docente","Para que todos pongan notas parecidas y no haya reclamos"]'::jsonb, 1, 'Sin calibración, los estudiantes evalúan con subjetividad. La calibración con ejemplos concretos alinea la comprensión de los criterios.', 'exam'),
('evaluacion', 13, '¿Cuál es la retroalimentación MÁS efectiva?', '["\"Excelente trabajo, se nota que te esforzaste mucho. Sigue así y vas a lograr todo lo que te propongas\"","\"Tu análisis de las causas fue sólido. Para mejorar, agrega evidencias de tu comunidad\"","\"Buen trabajo, aunque te faltaron algunos detalles\"","\"8/10. Revisa la ortografía\""]'::jsonb, 1, 'La retroalimentación efectiva es específica (qué estuvo bien y por qué), orientada al futuro (qué mejorar) y contextualizada (conecta con el aprendizaje real).', 'exam'),
('evaluacion', 14, 'Al evaluar un portafolio, ¿con qué debe compararse el trabajo del estudiante?', '["Con el portafolio del mejor estudiante del grupo","Con su propio trabajo del inicio del período para medir crecimiento","Con los estándares del grado","Con el promedio del grupo"]'::jsonb, 1, 'El portafolio es evidencia de crecimiento individual. La comparación relevante es el progreso del estudiante respecto a sí mismo.', 'exam'),
('evaluacion', 15, '¿Por qué los exámenes de opción múltiple no son suficientes para evaluar en un enfoque de competencias?', '["Porque facilitan que los estudiantes copien","Porque suelen medir recuerdo, no la aplicación en situaciones complejas","Porque las preguntas suelen ser demasiado fáciles","Porque toman mucho tiempo de calificar"]'::jsonb, 1, 'Las competencias implican aplicación en contextos reales. Los exámenes de opción múltiple miden el conocimiento declarativo pero no cómo se usa en situaciones auténticas.', 'exam'),
('evaluacion', 16, 'Una evaluación equitativa debe:', '["Dar exactamente las mismas tareas y tiempos a todos los estudiantes","Considerar las barreras de idioma, acceso a recursos y contexto socioeconómico en el diseño de las tareas","Basarse sobre todo en tareas para la casa, donde hay más tiempo","Usar siempre el mismo instrumento para que sea comparable"]'::jsonb, 1, 'La equidad en evaluación requiere que todos los estudiantes tengan la oportunidad real de demostrar su aprendizaje, sin ser obstaculizados por barreras ajenas al conocimiento.', 'exam'),
('evaluacion', 17, '¿Cómo puede la evaluación ser culturalmente sensible en contextos indígenas?', '["Aplicar el mismo instrumento a todos para que sea comparable","Valorar la demostración de conocimiento en lengua materna, formas de expresión diversas (oral, artística) y saberes locales","Evaluar en español para que el resultado sea oficial","Usar evaluaciones numéricas para evitar la subjetividad"]'::jsonb, 1, 'La evaluación culturalmente sensible reconoce que el conocimiento existe en múltiples formas y lenguas. Limitar la evaluación al español o formatos occidentales puede ocultar aprendizajes reales.', 'exam'),
('evaluacion', 18, '¿Cuál de estos es un error común al crear rúbricas?', '["Tener muy pocos criterios","Usar descriptores vagos como \"bien\" o \"regular\" en lugar de evidencias observables","Compartirlas con los estudiantes antes del trabajo","Incluir criterios de proceso además de producto"]'::jsonb, 1, 'Los descriptores vagos no sirven de guía ni para el estudiante ni para el docente. Los descriptores observables ("usa 3 fuentes") son específicos y aplicables.', 'exam'),
('evaluacion', 19, 'Un sistema de evaluación auténtico incluye:', '["Exámenes parciales, examen final y nota de participación","Diagnóstico, evaluación formativa, sumativa auténtica, auto y coevaluación","Proyectos durante el periodo, sin ningún tipo de examen","Exámenes semanales del libro de texto, un examen trimestral y una nota de conducta del docente"]'::jsonb, 1, 'Un sistema completo de evaluación auténtica integra múltiples tipos de evidencia, herramientas formativas continuas y la voz del estudiante como evaluador.', 'exam'),
('evaluacion', 20, 'Al crear una rúbrica, ¿qué nivel conviene describir primero?', '["El nivel más bajo, para tener claro cuál es el mínimo aceptable","El nivel excelente: qué se ve en un trabajo excepcional","El nivel intermedio","Ninguno: primero se asignan los puntos de cada criterio"]'::jsonb, 1, 'Describir el nivel excelente y luego los inferiores en relación con él produce descriptores coherentes y observables.', 'exam'),
('evaluacion', 21, 'Una docente quiere evaluar la colaboración y la perseverancia durante un proyecto. ¿Qué herramienta necesita?', '["Una rúbrica de producto","Una rúbrica de proceso, con observación y diarios de proyecto","Un examen de opción múltiple al final del proyecto sobre los contenidos","Una lista de asistencia"]'::jsonb, 1, 'Las competencias de proceso no se ven en el producto final; requieren observación durante el trabajo.', 'exam'),
('evaluacion', 22, 'Un estudiante selecciona sus mejores trabajos para mostrarlos a su familia al final del año. ¿Qué tipo de portafolio es?', '["Portafolio de trabajo (todo lo producido)","Portafolio de presentación","Portafolio de evaluación","Portafolio de proceso"]'::jsonb, 1, 'El de trabajo reúne todo lo producido; el de presentación, los mejores trabajos elegidos por el estudiante; el de evaluación, evidencias de competencias específicas.', 'exam'),
('evaluacion', 23, 'Al final de un tema, cada estudiante levanta una tarjeta roja, amarilla o verde según cuánto entendió. ¿Qué herramienta usa?', '["Semáforo de aprendizaje","Coevaluación","Rúbrica holística","Conferencia de portafolio"]'::jsonb, 0, 'El semáforo es una autoevaluación rápida que le da al docente información inmediata sobre el grupo.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('tipos-estudiantes', 0, '¿Cuál de los cuatro perfiles básicos del aula representa el mayor riesgo de abandono escolar sin ser detectado?', '["El estudiante comprometido que se exige demasiado","El estudiante desafiante","El estudiante invisible o conformista","El estudiante perfeccionista"]'::jsonb, 2, 'El estudiante invisible o conformista no activa las alertas del sistema porque no causa problemas y pasa sus materias. Puede estar sufriendo, perdido o en proceso de desenganche sin que nadie lo note.', 'exam'),
('tipos-estudiantes', 1, '¿Qué describe mejor el Efecto Pigmalión en el contexto educativo?', '["El fenómeno donde los estudiantes imitan la conducta de su docente favorito","Las expectativas del docente sobre sus estudiantes tienden a convertirse en profecías autocumplidas","La tendencia de los estudiantes brillantes a destacar sin importar el contexto ni lo que espere el docente","La influencia del grupo de compañeros en el rendimiento de cada estudiante"]'::jsonb, 1, 'El Efecto Pigmalión (Rosenthal y Jacobson, 1968) demostró que las expectativas del docente influyen directamente en el desempeño real de los estudiantes. Expectativas altas tienden a producir más logro; expectativas bajas, lo contrario.', 'exam'),
('tipos-estudiantes', 2, 'Diego habla con claridad y sofisticación pero entrega páginas en blanco en exámenes escritos. ¿Cuál es la interpretación más pedagógicamente responsable?', '["Diego es flojo y prefiere no esforzarse por escrito, así que lo mejor es exigirle más tareas escritas","Hay una brecha entre lo que demuestra de forma oral y lo que logra por escrito que debe explorarse, sin esperar un diagnóstico para apoyarlo","Diego tiene una discapacidad severa que requiere diagnóstico antes de actuar","Es una preferencia: hay que evaluarlo solo de forma oral de ahora en adelante"]'::jsonb, 1, 'La brecha entre desempeño oral y escrito sugiere que la lectoescritura está siendo una barrera para mostrar lo que sabe. El docente puede actuar de inmediato usando evaluación oral mientras se investiga más (y, si persiste, solicitar evaluación especializada).', 'exam'),
('tipos-estudiantes', 3, 'Un colega propone aplicar un test VARK y agrupar a los estudiantes en "visuales", "auditivos" y "kinestésicos". ¿Qué le respondes con base en la evidencia?', '["Que es buena idea: enseñar a cada grupo según su estilo mejora claramente sus resultados","Que no hay evidencia de que enseñar según el estilo mejore el aprendizaje","Que el test solo es válido en secundaria, así que en primaria conviene usar las inteligencias de Gardner","Que es mejor agrupar por inteligencias múltiples, porque esas sí tienen un diagnóstico preciso y estable"]'::jsonb, 1, 'Pashler et al. (2008) revisaron la evidencia y no encontraron apoyo para la idea de que adaptar la enseñanza al estilo preferido mejore el aprendizaje. Lo que funciona es elegir la representación según el contenido (mapas para geografía, audio para pronunciación) y combinar palabras con imágenes para todos.', 'exam'),
('tipos-estudiantes', 4, 'Una estudiante termina los ejercicios en la mitad del tiempo que sus compañeros y luego mira por la ventana. ¿Cuál es la respuesta más apropiada?', '["Pedirle que revise su trabajo varias veces para aprovechar el tiempo","Tener preparada una extensión genuinamente desafiante o un proyecto autónomo para cuando termine","Dejarla tranquila ya que no está causando problemas","Pedirle que ayude a explicar a los compañeros que van atrasados"]'::jsonb, 1, 'Un estudiante de alta capacidad que termina antes necesita estímulo intelectual genuino, no relleno de tiempo. "Revisa" raramente es desafiante. Una extensión real o proyecto autónomo aprovecha su capacidad y previene el desenganche.', 'exam'),
('tipos-estudiantes', 5, 'Marcos tiene conducta disruptiva en clase magistral pero lidera juegos complejos en el recreo. ¿Qué revela esta discrepancia?', '["Marcos se comporta según le conviene en cada ambiente","El formato de la clase magistral no le da a Marcos un rol activo, algo que sí tiene en el recreo","Marcos probablemente tiene TDAH y debe ser evaluado","En el recreo hay menos reglas, así que es lógico que se porte mejor"]'::jsonb, 1, 'El mismo estudiante puede ser "disruptivo" en un formato y "líder" en otro. Esto revela que la conducta está vinculada al diseño del ambiente, no a un defecto del estudiante. El docente puede canalizar las fortalezas de Marcos en el aula.', 'exam'),
('tipos-estudiantes', 6, '¿Qué es el Diseño Universal para el Aprendizaje (DUA)?', '["Un método para que las aulas físicas sean accesibles a sillas de ruedas","Un enfoque que diseña experiencias de aprendizaje accesibles para la mayor diversidad posible de estudiantes desde el inicio","Un currículo común que todos los países de la región deben seguir","La adaptación de la planificación para estudiantes con discapacidad certificada"]'::jsonb, 1, 'El DUA propone diseñar para la diversidad desde el principio, no hacer adaptaciones después. Sus tres principios son: múltiples formas de representación, de acción/expresión, y de compromiso.', 'exam'),
('tipos-estudiantes', 7, 'Ixchel responde correctamente cuando se le pregunta oralmente pero saca 55/100 en examen escrito. ¿Qué mide realmente ese 55?', '["Su comprensión del contenido evaluado, que es lo que pide el examen","Su comprensión del contenido mezclada con su dominio del español escrito","Que necesita estudiar más para los exámenes escritos","Su nivel de inteligencia general y su capacidad para aprender contenidos nuevos"]'::jsonb, 1, 'Cuando un estudiante bilingüe es evaluado solo en su segunda lengua y de forma escrita, la nota mezcla dos variables: comprensión del contenido Y dominio del español académico. Para medir solo el contenido, se necesitan modalidades alternativas.', 'exam'),
('tipos-estudiantes', 8, '¿Cuál es la intervención correcta ante el cambio brusco de comportamiento de un estudiante en un periodo de 2-4 semanas?', '["Informar a la familia de inmediato para que lo atiendan en casa","Investigar la causa antes de actuar: conversación privada, preguntas abiertas, escucha activa","Darle unas semanas: los cambios de conducta suelen pasar solos","Recordarle con firmeza las normas del aula, para que retome cuanto antes su conducta habitual"]'::jsonb, 1, 'El cambio brusco de comportamiento es una señal de que algo ocurrió en la vida del estudiante. Antes de reportar o sancionar, el docente debe investigar con una conversación privada y genuina.', 'exam'),
('tipos-estudiantes', 9, '¿Qué distingue a la motivación intrínseca de la extrínseca?', '["La intrínseca nace del interés propio; la extrínseca, de premios o castigos","La extrínseca es más duradera porque no depende del estado de ánimo","La intrínseca se logra sobre todo con buenas notas y reconocimiento","Ambas producen el mismo compromiso a largo plazo; lo único que cambia es de dónde vienen"]'::jsonb, 0, 'La motivación intrínseca nace del interés, la curiosidad o el propósito personal. La extrínseca depende de recompensas o castigos externos. Ambas coexisten, pero la intrínseca construye aprendizaje más duradero.', 'exam'),
('tipos-estudiantes', 10, '¿Qué es la diferenciación en la enseñanza?', '["Dar tareas más sencillas a quienes tienen dificultades","Ajustar el contenido, proceso, producto o ambiente para que todos accedan al mismo aprendizaje de calidad por distintas rutas","Crear un plan distinto para cada estudiante del grupo","Agrupar por nivel de rendimiento para que cada grupo avance a su ritmo"]'::jsonb, 1, 'Diferenciación no es reducir el nivel para algunos — es abrir múltiples rutas hacia el mismo aprendizaje de calidad. El destino es el mismo; el camino puede variar.', 'exam'),
('tipos-estudiantes', 11, 'Una docente llama a padres solo cuando hay problemas de conducta o notas bajas. ¿Qué impacto tiene esto sobre la alianza escuela-familia?', '["Ninguno: es la función normal de la comunicación escolar","Condiciona a los padres a asociar el contacto escolar con malas noticias, reduciendo su disposición a colaborar","Mejora la colaboración porque la familia se entera a tiempo de cada problema","Es lo más eficiente: no se quita tiempo a la familia con llamadas sin motivo"]'::jsonb, 1, 'Cuando el único contacto escuela-familia ocurre ante problemas, las familias aprenden a temerlo y evitarlo. La comunicación de logros positivos construye la alianza que permite manejar los problemas juntos cuando surgen.', 'exam'),
('tipos-estudiantes', 12, '¿Qué es el perfeccionismo patológico en un estudiante?', '["Un alto nivel de exigencia que conviene canalizar con metas más difíciles","Un miedo al error que paraliza: evita intentar y no tolera la imperfección","Un rasgo positivo que solo necesita reconocimiento por la calidad de su trabajo","Una señal de alta capacidad intelectual que pide más desafío"]'::jsonb, 1, 'El perfeccionismo patológico no es una virtud — es un mecanismo de defensa ante el miedo al juicio. Paraliza la experimentación y el aprendizaje, y puede derivar en ansiedad clínica si no se atiende.', 'exam'),
('tipos-estudiantes', 13, 'Un estudiante dice "odio la escuela". ¿Cuál es la respuesta más pedagógicamente efectiva?', '["\"La escuela es importante para tu futuro; vale la pena esforzarse.\"","\"¿Qué parte es la que más odias? Cuéntame.\" — y escucharlo","\"Entiendo, pero tienes que cumplir con tus tareas igual.\"","\"Todos sienten eso a veces, ya se te pasará.\""]'::jsonb, 1, 'El problema de "odio la escuela" es emocional y relacional, no cognitivo. Argumentar con razones racionales no funciona. Escuchar genuinamente — sin defender al sistema — es el primer paso para entender qué está detrás.', 'exam'),
('tipos-estudiantes', 14, '¿Qué significa el "todavía no" (growth mindset) cuando un estudiante fracasa?', '["Que aún no tiene la madurez necesaria y conviene esperar al próximo grado para retomarlo","El estudiante no lo ha logrado en este momento pero el camino sigue abierto","Que necesita más repetición del mismo ejercicio hasta lograrlo","Que el tema era muy difícil y conviene bajar el objetivo"]'::jsonb, 1, 'El "todavía no" de Carol Dweck transforma el fracaso en proceso. No cierra la posibilidad — la mantiene abierta. Es una intervención lingüística simple con impacto profundo en la motivación y la resiliencia.', 'exam'),
('tipos-estudiantes', 15, 'Sofía, 9 años, es extremadamente silenciosa desde el primer día. Una colega dice "es su personalidad, así ha sido siempre". ¿Cuál es la respuesta correcta?', '["Respetar su timidez y no intervenir para no presionarla","Investigar mediante observación y una conversación privada si hay algo más detrás del silencio","Pedirle que participe un poco cada día para que se acostumbre","Derivarla a psicología escolar desde la primera semana"]'::jsonb, 1, 'La timidez extrema persistente puede ser señal de ansiedad, bullying previo, barrera lingüística u otra situación. El primer paso es siempre observar e indagar mediante conversación privada, no ignorar ni forzar.', 'exam'),
('tipos-estudiantes', 16, '¿Cuál es la diferencia entre los canales BICS y CALP en estudiantes bilingües?', '["BICS es el dominio del lenguaje académico (5-7 años); CALP es la fluencia conversacional (1-2 años)","BICS: fluidez conversacional (1-2 años); CALP: lenguaje académico (5-7 años)","BICS es el idioma de la casa y CALP el de la escuela","BICS es la lectura y CALP la escritura"]'::jsonb, 1, 'BICS (fluencia conversacional) se desarrolla en 1-2 años en una segunda lengua. CALP (lenguaje académico) requiere 5-7 años. Ixchel puede tener BICS en español pero estar desarrollando su CALP — evaluar como si tuviera CALP penaliza su proceso normal.', 'exam'),
('tipos-estudiantes', 17, 'Al enfrentar a un estudiante nuevo marcado como "difícil" por docentes anteriores, ¿cuál es el primer paso correcto?', '["Establecer reglas claras desde el inicio para que sepa que en tu clase hay consecuencias","Conocerlo sin el filtro del expediente: construir relación antes de confrontar conducta","Llamar a los padres para comunicar las expectativas de comportamiento","Revisar su expediente para anticipar qué estrategias aplicar"]'::jsonb, 1, 'El primer día con un estudiante difícil es clave para construir — no destruir — la relación que hará posible el trabajo del año. El expediente contamina la percepción. La primera interacción debe ser de apertura, no de control.', 'exam'),
('tipos-estudiantes', 18, '¿Qué indica la investigación sobre el efecto de las expectativas del docente en el rendimiento de los estudiantes?', '["Las expectativas influyen poco: el rendimiento depende sobre todo del estudiante","Las expectativas altas del docente correlacionan con mayor logro; las bajas, con menor logro — independientemente del \"nivel\" del estudiante","Influyen más las expectativas de la familia que las del docente","Las expectativas altas presionan demasiado y reducen el rendimiento"]'::jsonb, 1, 'El Efecto Pigmalión y décadas de investigación posterior muestran que las expectativas del docente influyen en la conducta real del docente hacia el estudiante, que a su vez influye en el desempeño. Es una profecía autocumplida en ambas direcciones.', 'exam'),
('tipos-estudiantes', 19, 'Un plan de enseñanza diferenciada eficaz:', '["Requiere crear una planificación distinta para cada estudiante","Ofrece varias rutas hacia el mismo aprendizaje, según las necesidades del grupo","Funciona sobre todo en grupos pequeños y con un asistente en el aula","Le corresponde al equipo de educación especial, no al docente de aula regular del grupo"]'::jsonb, 1, 'La diferenciación efectiva no multiplica el trabajo del docente — lo rediseña. Tres rutas hacia el mismo aprendizaje son manejables. El principio es: mismo destino, distintos caminos.', 'exam'),
('tipos-estudiantes', 20, 'Según la síntesis de Hattie (2009), ¿qué lugar ocupa la relación docente-estudiante entre los factores que influyen en el rendimiento?', '["Tiene un efecto pequeño comparado con el tamaño del grupo","Está entre los factores de mayor influencia, por encima, por ejemplo, del tamaño del grupo","Importa sobre todo en primaria; en secundaria pesa más el contenido","Es menos importante que la experiencia y la formación del docente"]'::jsonb, 1, 'Conocer a los estudiantes y construir una relación positiva aparece entre los efectos más grandes sobre el aprendizaje.', 'exam'),
('tipos-estudiantes', 21, '¿Cómo deben entenderse los cuatro perfiles del aula (comprometido, conformista, invisible, disruptivo)?', '["Como categorías fijas para clasificar a cada estudiante todo el año","Como patrones flexibles: un estudiante puede moverse entre ellos según el día o lo que vive","Como un diagnóstico que orienta las adaptaciones","Como una forma de agrupar a los estudiantes por afinidad"]'::jsonb, 1, 'Los perfiles ayudan a observar, no a etiquetar: cambian con el contexto.', 'exam'),
('tipos-estudiantes', 22, '¿Cuáles son los tres principios del Diseño Universal para el Aprendizaje?', '["Diagnóstico, adaptación y evaluación diferenciada","Múltiples formas de representación, de acción y expresión, y de implicación","Agrupar a los estudiantes por niveles, adaptar el material y evaluar a cada grupo por separado","Tecnología, juego y trabajo en equipo para captar la atención"]'::jsonb, 1, 'El DUA diversifica cómo se presenta la información, cómo los estudiantes demuestran lo que saben y cómo se involucran.', 'exam'),
('tipos-estudiantes', 23, '¿Qué tres dimensiones se pueden diferenciar en la enseñanza, según el curso?', '["Contenido, proceso y producto","Ritmo, estilo y nivel de cada estudiante","Objetivo, tiempo y material","Instrucción, práctica y evaluación"]'::jsonb, 0, 'Se puede ajustar qué se aprende y con qué profundidad, por qué camino se llega y cómo se demuestra lo aprendido.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('storytelling', 0, 'Una docente describe tres opciones para iniciar su clase sobre un movimiento histórico de su país. ¿Cuál usa storytelling de forma más efectiva?', '["Muestra en la pizarra una línea de tiempo con las fechas clave del movimiento.","\"Hoy veremos un evento histórico muy importante para nuestro país. Anoten el título, la fecha y los tres personajes principales en su cuaderno.\"","\"Era una madrugada fría. Rosa, una maestra rural, se preguntaba si aún podía cambiar la vida de su pueblo.\"","Proyecta una imagen del líder del movimiento y pregunta qué saben de él."]'::jsonb, 2, 'La opción C tiene los tres elementos narrativos: personaje (Rosa), conflicto (¿es demasiado tarde?) y apertura emocional (la incertidumbre). Crea imagen mental, tensión y deseo de saber qué pasó. Las otras opciones anuncian información pero no generan experiencia.', 'lesson'),
('storytelling', 1, '¿Cuál de los siguientes enfoques pedagógicos se basa principalmente en los principios del storytelling?', '["Presentar el tema con una línea de tiempo bien ilustrada.","Pedir a los estudiantes que investiguen el tema y lo expongan.","Narrar un caso real con personaje, conflicto y resolución.","Poner un video explicativo sobre el tema y luego hacer un cuestionario."]'::jsonb, 2, 'El storytelling pedagógico se distingue por incorporar personaje, conflicto y resolución como vehículo del contenido. No es solo "usar ejemplos" — es construir una narrativa que hace que el contenido sea la respuesta a una pregunta que el estudiante quiere responder.', 'lesson'),
('storytelling', 2, '¿Por qué las historias suelen recordarse mejor que una lista de datos?', '["Porque se repiten más veces en clase que una lista de datos.","Porque organizan los datos en causas, consecuencias y emociones.","Porque los docentes las cuentan con más entusiasmo y eso basta.","Porque son más entretenidas, aunque el contenido quede en segundo plano."]'::jsonb, 1, 'Una historia conecta los datos en una secuencia causal con personajes y un conflicto: esa estructura facilita comprender y recuperar la información. Por eso los textos narrativos se recuerdan mejor que los expositivos (Mar et al., 2021). El entusiasmo ayuda, pero no explica el efecto.', 'lesson'),
('storytelling', 3, 'Una docente planifica su clase sobre la división con residuos usando este inicio: "Una comunidad rural necesita distribuir 253 bolsas de semillas entre 8 familias. Todas deben recibir lo mismo. ¿Cuántas bolsas sobran?" ¿Qué elemento narrativo está usando?', '["El viaje del héroe completo.","El arco problema-tensión-resolución con un contexto local.","La estructura de 5 actos completa.","El clímax narrativo sin exposición previa."]'::jsonb, 1, 'La docente usa el arco problema-tensión-resolución: hay un problema concreto (distribuir semillas), una tensión (¿cuántas sobran?, implica que el número no divide exactamente) y el contenido — la división con residuos — es la resolución. El contexto local hace el problema auténtico.', 'lesson'),
('storytelling', 4, 'Un docente quiere convertir el objetivo "el estudiante identificará las causas de la independencia de su país" en un gancho narrativo. ¿Cuál es la mejor versión?', '["\"El objetivo de hoy es identificar las causas de la independencia de nuestro país.\"","\"Una noche de principios del siglo XIX, unos líderes debatían en secreto si firmar un documento que podía costarles la vida. ¿Qué los llevó ahí?\"","\"Hoy veremos un hecho histórico muy importante: la independencia de nuestro país.\"","\"Abran el libro en la página 45 y lean con atención las causas de la Independencia. Después, copien en su cuaderno las cinco causas principales que aparecen en el recuadro azul.\""]'::jsonb, 1, 'La opción B convierte el objetivo en una historia: tiene personaje (un grupo de personas), conflicto (el riesgo de firmar), tensión (¿qué los llevó ahí?) y genera curiosidad antes de que el contenido empiece. Las causas de la Independencia se convierten en la respuesta a una pregunta que el estudiante quiere responder.', 'lesson'),
('storytelling', 5, '¿Cuál de estas acciones representa un uso efectivo de técnicas de narración en el aula?', '["Leer el texto del libro en voz alta con buena entonación.","Bajar la voz al llegar al momento más tenso de la historia, hacer una pausa de 3 segundos y luego continuar.","Mantener el mismo ritmo de voz para que todos sigan la historia.","Narrar de pie al frente del aula, sin moverse, para no distraer."]'::jsonb, 1, 'Bajar la voz (contraste de volumen) y la pausa dramática son técnicas de narración que crean tensión y señalan importancia. El cerebro del estudiante interpreta el contraste como "esto es lo que debo recordar". Hablar más rápido o quedarse detrás del escritorio reduce el impacto narrativo.', 'lesson'),
('storytelling', 6, '¿Qué error de narración "rompe la inmersión" de una historia en el aula de forma más severa?', '["Usar un ejemplo local en lugar de uno ajeno al contexto de los estudiantes.","Interrumpir la historia en el momento de mayor tensión para pasar lista o dar un anuncio administrativo.","Contar una historia que el docente no vivió personalmente.","Hacer una pregunta al grupo en medio del relato."]'::jsonb, 1, 'Interrumpir la tensión narrativa para asuntos administrativos destruye la inmersión. El cerebro del estudiante sale del estado de "historia" y entra al estado de "clase rutinaria" — y es difícil volver a entrar. La planificación debe proteger el arco narrativo de interrupciones predecibles.', 'lesson'),
('storytelling', 7, 'Una docente quiere evaluar si sus estudiantes comprendieron el ciclo del agua. En lugar de un examen escrito, les pide que narren la historia de "una gota de agua que comienza en la montaña y viaja hasta volver al punto de partida". ¿Qué tipo de evaluación es esta?', '["Una actividad de motivación que conviene complementar con un examen.","Una evaluación narrativa que mide comprensión profunda del ciclo del agua a través de la síntesis y la secuencia.","Una evaluación diagnóstica para saber qué sabían antes de empezar.","Una evaluación de la expresión oral más que del contenido científico."]'::jsonb, 1, 'Para narrar el viaje completo de la gota, el estudiante debe dominar la secuencia del ciclo del agua, sus etapas, los cambios de estado y los factores ambientales. La narrativa es el vehículo; la comprensión del ciclo es el contenido evaluado. Es evaluación auténtica y culturalmente contextualizada.', 'lesson'),
('storytelling', 8, '¿Cuál es la diferencia entre un objetivo de aprendizaje "embebido" en una historia y uno "declarado" antes de la clase?', '["No hay diferencia de fondo: en ambos casos el contenido es el mismo y solo cambia el momento en que se dice.","El objetivo embebido convierte el contenido en la respuesta a una pregunta que el estudiante ya quiere responder; el declarado lo presenta como una tarea externa.","El objetivo embebido es menos riguroso porque no se enuncia explícitamente.","El declarado es mejor porque los estudiantes saben desde el inicio qué se evalúa."]'::jsonb, 1, 'Cuando el objetivo se embebe en la historia, el estudiante aprende porque quiere resolver el conflicto narrativo — y el contenido es la clave para resolverlo. Eso es motivación intrínseca. Cuando se declara antes, el estudiante aprende porque el docente lo indicó. El contenido es el mismo; la motivación y la retención son muy distintas.', 'lesson'),
('storytelling', 9, 'Una docente comparte su gancho narrativo con un colega usando el protocolo "Noté / Me pregunté / ¿Qué pasaría si...?". El colega dice: "Noté que el conflicto se resuelve muy rápido en tu historia, en la segunda oración." ¿Qué debería hacer la docente con este feedback?', '["Mantener su versión: en el protocolo cada uno decide qué hacer con lo que oye.","Agradecer la observación y considerar extender la tensión del conflicto antes de ofrecer la resolución.","Defender su historia explicando por qué la resolución rápida es intencional.","Cambiar la historia completa por otra que el colega considere mejor."]'::jsonb, 1, 'El protocolo "Noté" es una observación descriptiva que da información útil sin juzgar. La resolución prematura del conflicto es efectivamente un riesgo narrativo: si la tensión no se sostiene lo suficiente, el cerebro no se involucra. La docente debe considerar cómo extender la tensión para que el conflicto "duela" un poco más antes de resolverse.', 'lesson'),
('storytelling', 10, 'Usas la "story spine" para planificar un gancho sobre la fotosíntesis. ¿Cuál de estas versiones sigue correctamente la estructura?', '["\"La fotosíntesis es el proceso por el cual las plantas producen su alimento usando luz solar, agua y dióxido de carbono.\"","\"Había una vez una hoja de maíz en un campo de la montaña. Cada día absorbía luz del sol y agua de la lluvia. Hasta que un día llegó una semana sin sol. Por eso, la hoja tuvo que buscar una manera de sobrevivir. Hasta que finalmente encontró reservas en su tallo. Y desde entonces, las plantas aprendieron a guardar energía para los días oscuros.\"","\"La planta es verde porque tiene clorofila. La clorofila absorbe luz y produce glucosa. Hasta que un día la planta deja de recibir luz. Por eso, la glucosa baja. Hasta que finalmente se marchita. Y desde entonces sabemos que la luz es importante para las plantas.\"","\"Hoy estudiaremos la fotosíntesis, que es muy importante para entender cómo crecen las plantas.\""]'::jsonb, 1, 'La opción B sigue exactamente la estructura de la story spine: personaje (hoja de maíz en un campo de la montaña), rutina (absorber sol y agua), detonante (semana sin sol), consecuencia (buscar solución), resolución (reservas en el tallo) y transformación (aprendieron a guardar energía). El contenido científico —fotosíntesis y almacenamiento de energía— está embebido en la narrativa.', 'lesson'),
('storytelling', 11, 'Una docente de Ciencias empieza su clase sobre erosión leyendo la definición del libro y luego cuenta una historia de una comunidad que perdió su ladera tras una lluvia fuerte. Los estudiantes participan mucho más durante la historia. ¿Qué principio del curso explica mejor esa diferencia?', '["Los datos aislados se recuerdan mejor si se leen en voz alta, con buena dicción y un ritmo constante, hasta que el grupo los repita.","La historia les da un personaje y un conflicto, así que el contenido se vuelve la respuesta a una pregunta que ya les importa.","Los estudiantes participan más cuando el docente cambia de actividad cada pocos minutos.","La historia es más sencilla que la definición, así que la entienden sin esfuerzo."]'::jsonb, 1, 'El curso propone embeber el objetivo en la historia: personaje, conflicto y resolución generan curiosidad y dan sentido al contenido. La historia no reemplaza el contenido ni depende solo de la voz.', 'exam'),
('storytelling', 12, 'Un docente narra una historia con mucho entusiasmo, pero a los 4 minutos nota que varios estudiantes miran por la ventana y los susurros aumentan. ¿Cuál es la mejor decisión según el curso?', '["Terminar la historia tal como la planificó para no perder el hilo, ya que modificar el relato confundiría al grupo.","Pedir silencio con firmeza y continuar desde donde iba.","Leer las señales del aula y ajustar en tiempo real: acelerar, hacer una pregunta o cambiar el ritmo.","Terminar rápido la historia y pasar al ejercicio del libro."]'::jsonb, 2, 'Un buen narrador observa a su público y ajusta el relato. Las señales de distracción piden cambiar ritmo, involucrar con una pregunta o acortar, no insistir ni abandonar la historia.', 'exam'),
('storytelling', 13, 'Una maestra quiere contar la historia de una comunidad indígena en su clase de Sociales. Sabe poco del tema y tiene un libro con una versión muy simplificada. ¿Qué debería hacer antes de contarla?', '["Contarla igual, porque cualquier historia local aporta identidad al grupo.","Investigar o consultar a personas de esa comunidad para evitar estereotipos y datos incorrectos.","Contarla con más detalles inventados para hacerla más atractiva.","Reemplazarla por una historia de otra cultura que conozca mejor."]'::jsonb, 1, 'El curso enfatiza la ética del storytelling: una historia con estereotipos o datos erróneos hace más daño que no contarla. Investigar y consultar antes de narrar es parte del trabajo.', 'exam'),
('storytelling', 14, 'Una docente quiere evaluar la comprensión del ciclo del agua sin un examen escrito. Pide a cada equipo narrar el viaje de una gota. ¿Qué debe incluir su rúbrica para que sea una evaluación válida?', '["La creatividad, la expresividad y la originalidad del relato.","El tiempo que dura la narración y la seguridad al hablar en público.","La precisión del contenido científico dentro de la narración, además de la claridad del relato.","La cantidad de personajes y la extensión de la historia, porque reflejan el esfuerzo que dedicó el estudiante."]'::jsonb, 2, 'La narrativa es el vehículo, pero lo evaluado es la comprensión del contenido. La rúbrica debe valorar la precisión conceptual y también la estructura del relato.', 'exam'),
('storytelling', 15, 'Una docente quiere iniciar una clase de historia sobre un hecho lejano en el tiempo. ¿Qué elemento narrativo ayuda más a que los estudiantes se conecten?', '["Un personaje con un deseo y un obstáculo que los estudiantes puedan reconocer como cercano.","Una lista de fechas y datos importantes en orden cronológico, para que los estudiantes la repasen antes de empezar.","Un resumen claro de los hechos al inicio, para que todos tengan el contexto.","Una pregunta inicial sobre qué recuerdan del tema."]'::jsonb, 0, 'El personaje y el conflicto generan identificación y curiosidad.', 'exam'),
('storytelling', 16, 'Un docente cuenta una historia muy emotiva, pero al terminar no relaciona el relato con el contenido. ¿Qué falló?', '["La historia fue demasiado corta para generar conexión.","No conectó la historia con el objetivo de aprendizaje mediante preguntas o una síntesis al cierre.","La historia debía ser completamente verídica, porque los estudiantes no aprenden de relatos inventados o ficticios.","Debió contarla al final de la clase, como cierre."]'::jsonb, 1, 'La historia sirve al aprendizaje cuando se vincula con el objetivo.', 'exam'),
('storytelling', 17, '¿Cuáles son los tres elementos esenciales de toda historia efectiva?', '["Inicio, desarrollo y final","Personaje, conflicto y resolución","Personaje, escenario y moraleja","Narrador, diálogo y desenlace"]'::jsonb, 1, 'Sin alguien con quien identificarse, un problema por resolver y un desenlace, no hay historia.', 'exam'),
('storytelling', 18, '¿Qué técnica consiste en terminar la clase en el momento de mayor tensión de la historia?', '["El cliffhanger","El callback final","La story spine","El mini-relato"]'::jsonb, 0, 'Dejar la historia abierta genera ganas de volver a la siguiente clase para saber qué pasa.', 'exam'),
('storytelling', 19, '¿Cómo está formado un mini-relato pedagógico?', '["Tres oraciones: personaje y situación, problema, y un giro que conecta con el contenido","Una historia breve de 2 a 3 minutos con moraleja final","Un dato sorprendente seguido de una pregunta","Una anécdota personal del docente sobre el tema"]'::jsonb, 0, 'No hace falta una historia larga: tres oraciones bien pensadas activan el poder narrativo.', 'exam'),
('storytelling', 20, 'Una docente presenta las fracciones como ''hermanas que deben compartir exactamente un pastel''. ¿Qué técnica usa?', '["Personificar un concepto abstracto","Mostrar un dato estadístico sorprendente","Evaluación narrativa","Callback"]'::jsonb, 0, 'Dar nombre, personalidad y problema a un concepto abstracto lo vuelve más memorable.', 'exam'),
('storytelling', 21, '¿Qué significa el principio ''muestra, no digas'' en la docencia?', '["Usar imágenes y videos en lugar de explicar con palabras","Describir detalles concretos que dejen sentir la situación, en vez de solo afirmarla","Decir la conclusión al inicio de la clase para que todos sepan hacia dónde va la historia","Hacer demostraciones prácticas en vez de narrar"]'::jsonb, 1, 'En vez de decir ''la pobreza era dura'', se describen escenas concretas que permiten imaginarla.', 'exam'),
('storytelling', 22, 'Un docente, al final de la clase, retoma una frase de la historia del inicio: ''como el personaje que no se rindió…''. ¿Qué técnica aplica?', '["Callback","Cliffhanger","Story spine","Silencio de anticipación"]'::jsonb, 0, 'Volver a un elemento anterior de la historia refuerza la idea clave y cierra el círculo.', 'exam'),
('storytelling', 23, '¿Por qué el curso propone que los estudiantes sean narradores, no solo público?', '["Porque así participan más y el docente puede observarlos mejor","Porque crear y contar una historia del contenido exige comprenderlo y organizarlo","Porque las historias de sus compañeros los entretienen mucho más que las del docente","Porque es una forma de practicar la expresión oral frente al grupo"]'::jsonb, 1, 'Narrar el contenido obliga a ordenar ideas, causas y consecuencias: es una forma profunda de aprender.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('creatividad', 0, '¿Cuál de las siguientes afirmaciones sobre la creatividad es CORRECTA?', '["La creatividad es un talento innato que se puede estimular un poco, pero no desarrollar de verdad.","La creatividad aparece sobre todo en las artes y en el lenguaje.","La creatividad es una habilidad que cualquier persona puede desarrollar con práctica.","La creatividad tiene poca aplicación en materias como matemáticas."]'::jsonb, 2, 'La creatividad es una habilidad humana universal que puede cultivarse. La investigación en neurociencia y educación confirma que todos podemos volvernos más creativos con las condiciones y prácticas adecuadas.', 'lesson'),
('creatividad', 1, 'Según el Foro Económico Mundial, ¿por qué la creatividad es tan importante para el siglo XXI?', '["Porque las empresas buscan sobre todo personas con habilidades artísticas.","Porque permite a las personas generar ideas originales y adaptarse ante un mundo cambiante.","Porque es la única habilidad que la tecnología no podrá reemplazar en ningún tipo de trabajo.","Porque es más importante que el conocimiento técnico en el futuro laboral."]'::jsonb, 1, 'En un mundo donde la automatización realiza tareas rutinarias, la creatividad —la capacidad de generar ideas originales, resolver problemas nuevos y adaptarse— se convierte en una ventaja humana fundamental.', 'lesson'),
('creatividad', 2, '¿Cuál es el orden correcto de las etapas del ciclo creativo?', '["Iluminación → Preparación → Incubación → Verificación","Preparación → Incubación → Iluminación → Verificación","Verificación → Preparación → Iluminación → Incubación","Incubación → Iluminación → Preparación → Verificación"]'::jsonb, 1, 'El ciclo creativo comienza con la Preparación (acumular experiencias e información), sigue con la Incubación (procesamiento inconsciente), luego viene la Iluminación (la idea surge) y finalmente la Verificación (se evalúa y perfecciona la idea).', 'lesson'),
('creatividad', 3, '¿Qué caracteriza principalmente al pensamiento divergente?', '["Encontrar la única respuesta correcta a un problema complejo.","Evaluar críticamente cada idea antes de aceptarla.","Generar la mayor cantidad posible de ideas sin juzgarlas.","Seguir un proceso lógico paso a paso."]'::jsonb, 2, 'El pensamiento divergente se trata de generar múltiples ideas posibles sin juzgarlas de inmediato. Es la fase ''abierta'' de la creatividad donde la cantidad y variedad de ideas importan más que su calidad inicial.', 'lesson'),
('creatividad', 4, '¿Qué efecto tienen las emociones positivas como la curiosidad y la alegría sobre la creatividad?', '["La reducen porque distraen del pensamiento lógico.","Ayudan a la motivación, pero no influyen en la generación de ideas.","La amplifican al abrir la mente a más posibilidades.","Ayudan solo si la tarea es artística."]'::jsonb, 2, 'Las emociones positivas amplían nuestra capacidad de generar ideas (teoría ''broaden and build''). Por eso un ambiente emocionalmente seguro y positivo en el aula es condición necesaria para que emerja la creatividad.', 'lesson'),
('creatividad', 5, '¿Qué es la ''incubación'' en el proceso creativo?', '["Una técnica para generar muchas ideas en poco tiempo.","El período en que el cerebro procesa ideas inconscientemente mientras descansamos.","Una estrategia para evaluar críticamente las ideas generadas.","El momento en que la idea aparece de forma repentina."]'::jsonb, 1, 'La incubación es la fase en que dejamos de esforzarnos conscientemente en un problema y el cerebro sigue procesando en segundo plano. Ocurre durante descansos, paseos o el sueño, y con frecuencia produce los ''momentos eureka''.', 'lesson'),
('creatividad', 6, 'En la técnica SCAMPER, ¿qué representa la letra ''A''?', '["Ampliar","Asociar","Adaptar","Agregar"]'::jsonb, 2, 'En SCAMPER, la ''A'' representa Adaptar: preguntarte cómo podrías adaptar el objeto, proceso o idea a otro contexto, uso o grupo de personas. Es una de las preguntas más poderosas para generar variantes creativas.', 'lesson'),
('creatividad', 7, 'En la técnica de los ''6 Sombreros para Pensar'' de De Bono, ¿qué representa el sombrero VERDE?', '["Pensar en los riesgos y peligros de una idea.","Analizar los datos y hechos disponibles.","Expresar emociones e intuiciones sobre el tema.","Generar ideas creativas y alternativas nuevas."]'::jsonb, 3, 'El sombrero verde representa el pensamiento creativo: generar nuevas ideas, alternativas y posibilidades sin juzgarlas. Es el sombrero de la creatividad y la innovación dentro de la dinámica de los 6 sombreros.', 'lesson'),
('creatividad', 8, '¿Por qué las RESTRICCIONES pueden potenciar la creatividad?', '["Porque reducen el número de ideas y así es más fácil elegir.","Porque obligan a la mente a encontrar soluciones ingeniosas dentro de límites definidos.","Porque dan una única respuesta correcta a la que hay que llegar.","Porque hacen que la actividad sea más sencilla de completar."]'::jsonb, 1, 'Las restricciones enfocan la mente y la obligan a ser ingeniosa dentro de límites específicos. Paradójicamente, tener recursos o posibilidades ilimitadas puede inhibir la creatividad, mientras que las restricciones claras la activan.', 'lesson'),
('creatividad', 9, '¿Cuál es la actitud más adecuada hacia el error en un ambiente creativo de aprendizaje?', '["El error debe evitarse en lo posible porque genera malos hábitos.","El error se acepta en actividades libres, pero conviene evitarlo en las que se evalúan.","El error es fuente de información y parte natural del proceso de aprendizaje.","El error debe corregirse de inmediato para no reforzarlo."]'::jsonb, 2, 'En ambientes creativos, el error es visto como información valiosa, no como fracaso. Esta mentalidad (''growth mindset'') permite que los estudiantes tomen riesgos intelectuales y exploren con mayor profundidad.', 'lesson'),
('creatividad', 10, '¿Cuál de las siguientes es una pregunta ABIERTA que promueve el pensamiento creativo?', '["¿Qué causas tuvo el tratado de paz firmado en nuestro país?","¿Cuántos tipos de triángulos existen según sus lados?","¿Qué diferencias hay entre la capital y nuestra comunidad?","¿Cómo crees que cambiaría nuestra comunidad si todos tuviéramos acceso a internet?"]'::jsonb, 3, 'La pregunta sobre cómo cambiaría la comunidad con acceso universal a internet es abierta: no tiene una sola respuesta correcta, invita a explorar, imaginar y argumentar. Ese tipo de preguntas activan el pensamiento creativo y crítico.', 'lesson'),
('creatividad', 11, '¿Por qué los portafolios son más compatibles con ambientes creativos que los exámenes tradicionales?', '["Porque permiten calificar de forma más rápida que un examen.","Porque reemplazan la necesidad de dar una nota al estudiante.","Porque permiten valorar el proceso creativo y la evolución del estudiante, no solo el producto final.","Porque reducen la ansiedad del estudiante al final del periodo."]'::jsonb, 2, 'Los portafolios documentan el proceso creativo a lo largo del tiempo: muestran borradores, errores, revisiones y aprendizajes. Esto los hace mucho más ricos para evaluar la creatividad que un examen que solo captura un momento final.', 'lesson'),
('creatividad', 12, '¿Qué significa que un docente sea ''modelo creativo'' para sus estudiantes?', '["Que domina varias técnicas de creatividad y las enseña con frecuencia.","Que diseña actividades originales para cada clase.","Que experimenta, admite sus dudas y celebra las ideas inusuales frente a sus estudiantes.","Que prepara clases muy elaboradas y visualmente atractivas."]'::jsonb, 2, 'Ser modelo creativo significa encarnar la mentalidad creativa: atreverse a experimentar, admitir incertidumbre y celebrar las ideas diferentes. Los estudiantes aprenden más de los comportamientos que observan que de las instrucciones que reciben.', 'lesson'),
('creatividad', 13, '¿Cuál es un beneficio clave de las comunidades de práctica creativa entre docentes?', '["Permiten repartir la planificación entre colegas para ahorrar tiempo de preparación.","Multiplican las ideas al compartir y construir sobre las experiencias de colegas.","Reemplazan la necesidad de formación individual continua.","Aseguran que todas las clases sigan el mismo formato creativo."]'::jsonb, 1, 'Las comunidades de práctica multiplican la creatividad: cuando los docentes comparten estrategias y se dan retroalimentación, una idea se transforma y mejora colectivamente. La creatividad colaborativa supera a la individual.', 'lesson'),
('creatividad', 14, '¿Cuál de las siguientes afirmaciones resume mejor el mensaje central de este curso?', '["La creatividad es un talento innato: algunos docentes lo traen y otros, por más que practiquen, no logran desarrollarlo.","Para ser creativo, un docente necesita recursos materiales y tiempo para planificar.","La creatividad es una habilidad que cualquier docente puede cultivar y que transforma el aprendizaje cuando se modela y se practica conscientemente.","La creatividad en el aula se desarrolla sobre todo con actividades artísticas y de juego."]'::jsonb, 2, 'Este curso sostiene que la creatividad es una habilidad universal, cultivable, que va mucho más allá del arte. Cuando un docente la práctica conscientemente —usando técnicas, creando ambientes seguros y modelándola con su propia actitud— transforma profundamente la experiencia de aprendizaje de sus estudiantes.', 'lesson'),
('creatividad', 15, 'Una docente dice ''yo no soy creativa, eso es para artistas''. ¿Qué respuesta del curso es más adecuada?', '["Tiene algo de razón: hay personas más creativas que otras por naturaleza.","Se desarrolla sobre todo en la infancia; de adulto es más difícil.","Depende sobre todo del hemisferio derecho, así que algunas personas tienen una clara ventaja natural.","La creatividad se puede desarrollar y se manifiesta en cualquier disciplina, no solo en el arte."]'::jsonb, 3, 'Mitos sobre la creatividad.', 'exam'),
('creatividad', 16, 'En una lluvia de ideas, un estudiante critica cada propuesta apenas se dice. ¿Qué regla del brainstorming se rompe?', '["Elegir una sola idea desde el inicio para profundizar en ella con todo el grupo.","Posponer el juicio: primero cantidad de ideas, luego evaluación.","Dar a cada persona el mismo tiempo para hablar.","Construir sobre las ideas de los demás."]'::jsonb, 1, 'Pensamiento divergente antes del convergente.', 'exam'),
('creatividad', 17, 'Una docente quiere mejorar la actividad ''dibujar un mapa del barrio''. Se pregunta: ¿qué puedo sustituir, combinar o eliminar? ¿Qué técnica aplica?', '["Mapas mentales, que organizan ideas alrededor de un concepto central.","Seis sombreros para pensar.","SCAMPER, que usa preguntas para transformar una idea existente.","Método de los 5 Porqués."]'::jsonb, 2, 'SCAMPER: sustituir, combinar, adaptar, modificar, proponer otros usos, eliminar, reordenar.', 'exam'),
('creatividad', 18, 'Un docente tiene poco material y su grupo no parece tener ideas. ¿Qué enfoque del curso puede ayudar?', '["Esperar a tener más recursos para hacer la actividad completa.","Mostrar un ejemplo terminado para que todos lo reproduzcan.","Usar una restricción creativa, como resolver el reto con solo tres materiales.","Dar más tiempo de lluvia de ideas libre, sin ninguna consigna."]'::jsonb, 2, 'Las restricciones pueden potenciar la creatividad.', 'exam'),
('creatividad', 19, 'Un estudiante entrega un proyecto distinto a lo esperado y con un fallo evidente. ¿Qué reacción favorece un ambiente creativo?', '["Calificarlo según la rúbrica original, aunque el proyecto no se ajuste a lo que se pidió.","Compararlo con un trabajo bien logrado para que vea la diferencia.","Preguntar qué aprendió del fallo y qué cambiaría, tratando el error como información.","Pedir que lo rehaga para que se ajuste a lo que se esperaba."]'::jsonb, 2, 'El error como parte del aprendizaje.', 'exam'),
('creatividad', 20, 'Una docente evalúa un proyecto creativo solo con un examen de memoria sobre el tema. ¿Qué problema tiene?', '["Ninguno, porque comprueba que domina el contenido.","Que el examen debería incluir también preguntas de aplicación.","Que debería combinarlo con una nota de participación.","La evaluación tradicional puede frenar la creatividad; conviene usar rúbricas, portafolios o procesos."]'::jsonb, 3, 'Evaluación en ambientes creativos.', 'exam'),
('creatividad', 21, 'Un docente teme hacer una actividad nueva por miedo al ridículo frente a sus colegas. ¿Qué estrategia propone el curso?', '["Compartir pequeñas pruebas con una comunidad de práctica de confianza y aprender de ellas.","Esperar a tener la actividad bien planificada y probada antes de mostrársela a cualquier colega.","Pedir a la dirección que la apruebe antes de aplicarla.","Probarla primero sola, sin comentar nada hasta ver si funciona."]'::jsonb, 0, 'Superar el miedo al ridículo y comunidades de práctica.', 'exam'),
('creatividad', 22, '¿Qué dice hoy la neurociencia sobre la idea de que la creatividad vive en el ''hemisferio derecho''?', '["Que es correcta: la creatividad se concentra en el hemisferio derecho","Que es un mito: la creatividad involucra varias redes cerebrales que trabajan juntas","Que depende del hemisferio izquierdo, que es el que genera ideas","Que depende sobre todo de la inteligencia general de la persona"]'::jsonb, 1, 'La creatividad combina redes que generan ideas (imaginación) y redes que las evalúan; no depende de un solo hemisferio.', 'exam'),
('creatividad', 23, 'En una actividad, cada estudiante acepta la idea del anterior y le agrega algo nuevo. ¿Qué técnica es?', '["''Sí, y…'', tomada del teatro de improvisación","Seis sombreros para pensar","Votación de puntos","SCAMPER"]'::jsonb, 0, '''Sí, y…'' crea cadenas de ideas que se construyen unas sobre otras, sin bloqueos ni juicios.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('herramientas-tec', 0, 'Según el modelo SAMR, ¿cuál de los siguientes usos representa el nivel más ALTO de integración tecnológica?', '["El estudiante escribe su tarea en Google Docs en lugar de cuaderno.","El estudiante usa el corrector automático y el historial de versiones de Google Docs para revisar su texto.","El estudiante crea un blog multilingüe en colaboración con estudiantes de otro país.","El estudiante busca información en internet para hacer su tarea."]'::jsonb, 2, 'Crear un blog colaborativo con estudiantes de otro país es Redefinición: es una tarea completamente nueva que sería imposible sin tecnología. Los otros ejemplos representan Sustitución o Aumento, niveles más básicos del modelo SAMR.', 'lesson'),
('herramientas-tec', 1, 'Un docente pide a sus estudiantes que graben un video explicando un concepto científico con sus propias palabras y analogías. ¿En qué nivel de la Taxonomía de Bloom se ubica esta actividad?', '["Recordar","Comprender","Aplicar","Crear"]'::jsonb, 3, 'Crear un video explicativo con analogías propias es un nivel de Creación (el más alto de la Taxonomía de Bloom): el estudiante no solo recuerda o comprende, sino que produce algo nuevo que sintetiza y comunica el conocimiento de manera original.', 'lesson'),
('herramientas-tec', 2, '¿Cuál es la práctica más adecuada para proteger los derechos digitales de los estudiantes?', '["Publicar fotos de las actividades del aula en redes sociales para mostrar a la comunidad el trabajo de la clase.","Solicitar consentimiento informado de padres antes de publicar imágenes o trabajos de estudiantes en línea.","Usar los nombres completos de los estudiantes en las plataformas para identificarlos.","Pedir a los estudiantes que usen su correo personal para registrarse."]'::jsonb, 1, 'Siempre se requiere consentimiento informado de padres o tutores antes de publicar fotos, nombres o trabajos de estudiantes menores de edad en línea. Esta es una obligación ética y legal del docente.', 'lesson'),
('herramientas-tec', 3, '¿Cuál es el enfoque más efectivo para integrar herramientas tecnológicas en el aula?', '["Usar la mayor variedad posible de herramientas para mantener el interés.","Dominar pocas herramientas seleccionadas con criterio pedagógico y usarlas con propósito claro.","Elegir siempre las herramientas más recientes y populares.","Dejar que los estudiantes elijan qué herramientas usar sin guía del docente."]'::jsonb, 1, 'La efectividad no viene de usar muchas herramientas, sino de usar pocas bien. Dominar a fondo herramientas seleccionadas permite al docente usarlas con más confianza, creatividad y propósito pedagógico claro.', 'lesson'),
('herramientas-tec', 4, '¿Cuál de las siguientes NO es una funcionalidad de Canva para Educación?', '["Crear presentaciones visuales con plantillas.","Asignar proyectos de diseño a estudiantes y comentar sus trabajos.","Realizar videoconferencias en tiempo real con toda la clase.","Diseñar infografías y materiales didácticos visuales."]'::jsonb, 2, 'Canva no es una plataforma de videoconferencias. Su función principal es el diseño gráfico: crear presentaciones, infografías, videos cortos y materiales visuales. Para videoconferencias, se usan herramientas como Google Meet o Zoom.', 'lesson'),
('herramientas-tec', 5, '¿Cuál es la ventaja principal de usar Google Slides frente a PowerPoint tradicional en el aula?', '["Tiene más plantillas de diseño disponibles para el aula.","Permite la colaboración en tiempo real desde diferentes dispositivos sin necesidad de enviar archivos.","Funciona sin conexión a internet en todos los dispositivos.","Tiene más animaciones y transiciones que PowerPoint."]'::jsonb, 1, 'La ventaja clave de Google Slides es la colaboración en tiempo real: múltiples usuarios pueden editar simultáneamente desde cualquier dispositivo, sin necesidad de enviar archivos por correo. Esto transforma las presentaciones en herramientas de trabajo colaborativo.', 'lesson'),
('herramientas-tec', 6, '¿Cuál es la duración óptima recomendada para un video educativo que maximice la atención de los estudiantes?', '["Más de 30 minutos para cubrir el tema completo.","Entre 15 y 20 minutos, como una clase magistral.","Menos de 3 a 7 minutos, dividiendo temas largos en partes.","Alrededor de 10 a 12 minutos, sin importar la edad del grupo ni el tema."]'::jsonb, 2, 'Los videos de 3 a 7 minutos tienen tasas de visualización completa mucho más altas. La atención decae significativamente después de ese tiempo. Para temas largos, es mejor crear series de videos cortos que un solo video extenso.', 'lesson'),
('herramientas-tec', 7, '¿En qué momento de la clase es más útil usar Mentimeter para crear una nube de palabras?', '["Al final del examen como actividad de celebración.","Durante la clase magistral para ilustrar conceptos.","Al inicio de clase para activar conocimiento previo de manera visual y participativa.","Al final de la clase, para calificar la participación de cada estudiante."]'::jsonb, 2, 'La nube de palabras de Mentimeter es especialmente poderosa al inicio de clase: activa el conocimiento previo, hace visible lo que los estudiantes ya saben, genera curiosidad y permite al docente ajustar su clase según las respuestas en tiempo real.', 'lesson'),
('herramientas-tec', 8, '¿Cuál es el principal propósito pedagógico de usar Kahoot en el aula?', '["Reemplazar los exámenes escritos tradicionales con una nota automática que va directo al registro oficial.","Verificar la comprensión de manera gamificada y obtener retroalimentación inmediata sobre el aprendizaje.","Calificar a los estudiantes de forma rápida y objetiva.","Motivar al grupo con una competencia al final de la clase."]'::jsonb, 1, 'Kahoot es principalmente una herramienta de evaluación formativa gamificada: verifica comprensión de manera entretenida y proporciona retroalimentación inmediata tanto al docente como a los estudiantes. No es una herramienta de calificación sumativa.', 'lesson'),
('herramientas-tec', 9, '¿Cuál es la diferencia principal entre Kahoot y Quizizz?', '["Kahoot es gratuito y Quizizz requiere una suscripción de pago para cada estudiante.","Kahoot funciona en computadoras y Quizizz en teléfonos.","En Quizizz los estudiantes responden a su propio ritmo, mientras en Kahoot todos responden al mismo tiempo bajo presión.","Quizizz no muestra los resultados al docente en tiempo real."]'::jsonb, 2, 'La diferencia clave es el ritmo: Kahoot es sincrónico (todos al mismo tiempo, con presión de tiempo colectivo), mientras Quizizz es a ritmo propio (cada estudiante avanza cuando está listo). Esto hace a Quizizz más inclusivo para estudiantes que necesitan más tiempo.', 'lesson'),
('herramientas-tec', 10, '¿Qué ventaja ofrece la corrección automática de Google Forms frente a la corrección manual?', '["La corrección automática es más justa porque elimina todo sesgo del docente.","Los estudiantes reciben retroalimentación inmediata y el docente ahorra tiempo de corrección.","Permite evaluar respuestas abiertas igual de bien que un docente.","La corrección automática mejora la calificación de todos los estudiantes."]'::jsonb, 1, 'La corrección automática permite que los estudiantes reciban retroalimentación inmediata (saben qué acertaron y qué no, con explicaciones) y el docente no invierte tiempo en corregir manualmente. Esto libera tiempo para actividades de mayor impacto.', 'lesson'),
('herramientas-tec', 11, '¿Cuál herramienta es más apropiada para que un docente recoja reflexiones escritas y abiertas de sus estudiantes al finalizar una unidad?', '["Kahoot, porque es rápido y motiva al grupo.","Google Forms con preguntas de texto largo o Padlet con publicaciones libres.","Quizizz, porque los estudiantes responden a su propio ritmo.","Mentimeter con una nube de palabras."]'::jsonb, 1, 'Para recoger reflexiones escritas abiertas, Google Forms con preguntas de texto largo o Padlet son las opciones más adecuadas. Kahoot y Quizizz están diseñados principalmente para preguntas cerradas de opción múltiple, no para reflexiones elaboradas.', 'lesson'),
('herramientas-tec', 12, '¿Cuál es la función principal de Google Classroom en el aula?', '["Crear presentaciones colaborativas.","Realizar videoconferencias con estudiantes y grabarlas automáticamente para que las vean después.","Organizar materiales, tareas, retroalimentación y avisos en un solo lugar.","Diseñar cuestionarios gamificados para evaluación."]'::jsonb, 2, 'Google Classroom es un LMS (Sistema de Gestión del Aprendizaje): su función es centralizar la gestión del aula —materiales, tareas, calificaciones, retroalimentación y comunicación— en una sola plataforma integrada y gratuita.', 'lesson'),
('herramientas-tec', 13, '¿Qué es el ''phishing'' en el contexto de la seguridad digital?', '["Un virus que se instala al abrir archivos adjuntos.","Una técnica para piratear software educativo de pago y distribuirlo gratis entre docentes por correo.","Un engaño mediante correos o mensajes falsos que buscan robar contraseñas o información personal.","Una forma de publicidad engañosa en redes sociales."]'::jsonb, 2, 'El phishing consiste en correos, mensajes o sitios web falsos que imitan ser legítimos (un banco, una plataforma educativa, una institución) para engañar al usuario y robar sus contraseñas o información personal. Reconocer estas señales es esencial para la seguridad digital.', 'lesson'),
('herramientas-tec', 14, 'Un estudiante encuentra una imagen en internet y quiere usarla en su presentación escolar. ¿Cuál es la acción más correcta de ciudadanía digital?', '["Usarla, porque es para un trabajo escolar y no se va a vender.","Verificar si tiene licencia Creative Commons o permiso de uso libre, y si es así, usarla citando la fuente.","Usarla si se le hacen cambios para que sea una obra ''distinta''.","Usarla citando el sitio donde la encontró, aunque no tenga licencia libre."]'::jsonb, 1, 'El hecho de que una imagen esté en internet no significa que sea de libre uso. Lo correcto es verificar la licencia (buscar imágenes con licencia Creative Commons), y siempre citar la fuente. Esto enseña respeto a los derechos de autor desde edades tempranas.', 'lesson'),
('herramientas-tec', 15, '¿Cuál es la afirmación que mejor resume el enfoque de integración tecnológica de este curso?', '["Usar la mayor cantidad de herramientas tecnológicas posibles garantiza mejor aprendizaje.","La tecnología debe reemplazar gradualmente los métodos tradicionales, porque los estudiantes de hoy aprenden mejor con pantallas.","La tecnología es una herramienta poderosa cuando se selecciona con criterio, se usa con propósito pedagógico claro y se combina con buenas prácticas de seguridad y ciudadanía digital.","Los docentes deben usar tecnología solo cuando tengan capacitación certificada en cada herramienta."]'::jsonb, 2, 'Este curso sostiene que la tecnología no es magia ni sustituto de la buena pedagogía: es una herramienta poderosa cuando se elige con criterio, se usa con propósito claro de aprendizaje y se acompaña de responsabilidad digital. El docente que integra tecnología con estos principios transforma su práctica de manera sostenible.', 'lesson'),
('herramientas-tec', 16, 'Una docente reemplaza el cuaderno por una hoja digital con los mismos ejercicios. Según SAMR, ¿en qué nivel está?', '["Sustitución, porque cambia el soporte sin cambiar la tarea.","Redefinición, porque pasar de papel a pantalla transforma la tarea.","Modificación, porque se usa una pantalla.","Aumento, porque los archivos quedan guardados."]'::jsonb, 0, 'SAMR: la tecnología debe agregar valor pedagógico.', 'exam'),
('herramientas-tec', 17, 'Una escuela no tiene internet estable. ¿Qué planificación tecnológica es más sensata?', '["Dejar las actividades con tecnología solo para las semanas en que haya conexión.","Planificar con tecnología y, si falla, explicar el tema en la pizarra.","Pedir que los estudiantes usen sus datos móviles durante la clase.","Preparar contenido para usar sin conexión y tener un plan B sin tecnología."]'::jsonb, 3, 'Conectividad y plan B.', 'exam'),
('herramientas-tec', 18, 'Un docente quiere usar una app gratuita que pide el nombre completo y correo personal de los estudiantes. ¿Qué debe considerar?', '["Usarla, porque es gratuita y la escuela no tiene presupuesto.","Crear una cuenta compartida para todo el grupo con los datos del docente.","Pedir a las familias que registren ellas a sus hijos, sin explicar para qué se usarán los datos.","Proteger la privacidad: revisar las condiciones y buscar alternativas que no expongan datos."]'::jsonb, 3, 'Derechos digitales de los estudiantes.', 'exam'),
('herramientas-tec', 19, 'Una docente quiere comprobar quién entendió la clase en 5 minutos, sin calificarlo. ¿Qué enfoque es adecuado?', '["Un examen corto con nota para saber quién entendió.","Esperar a la tarea para ver quién entendió, sin preguntar en clase.","Preguntar al grupo ''¿entendieron?'' y seguir si nadie dice que no.","Una evaluación formativa con una pregunta rápida en un formulario o tablero colaborativo."]'::jsonb, 3, 'Evaluación formativa durante el proceso.', 'exam'),
('herramientas-tec', 20, 'Un docente usaba Jamboard y fue descontinuada. ¿Qué lección apunta el curso?', '["Evitar las herramientas gratuitas.","Pasarse a la herramienta más parecida y seguir trabajando igual que antes.","Usar solo herramientas de pago, porque esas no se descontinúan.","Elegir herramientas por criterios pedagógicos y revisar su vigencia, para no depender de una sola."]'::jsonb, 3, 'El docente como curador de tecnología.', 'exam'),
('herramientas-tec', 21, 'Una docente comparte con sus estudiantes una contraseña simple como ''123456''. ¿Qué debería enseñar?', '["Usar su nombre y fecha de nacimiento, para que sea fácil de recordar.","Cambiarla cada semana, aunque siga siendo simple.","Contraseñas largas y únicas, con combinaciones, y no compartirlas.","Usar una contraseña común para el grupo, que guarde el docente."]'::jsonb, 2, 'Contraseñas seguras.', 'exam'),
('herramientas-tec', 22, 'Un docente diseña una tarea en la que los estudiantes crean y publican un podcast con ayuda de una herramienta. ¿Qué nivel de Bloom y SAMR favorece?', '["Niveles altos: crear en Bloom y redefinición o modificación en SAMR.","Recordar y sustitución, porque se trata de repetir información con una herramienta nueva.","Comprender y aumento, porque explican lo que entendieron del tema.","Aplicar y modificación, porque usan una herramienta para resolver una tarea."]'::jsonb, 0, 'Tecnología con propósito: tareas de orden superior.', 'exam'),
('herramientas-tec', 23, 'Una docente nota que solo algunos estudiantes tienen dispositivo en casa. ¿Qué decisión favorece la inclusión digital?', '["Asignar la tarea digital a quienes tienen dispositivo y otra distinta al resto.","Ofrecer momentos de uso en la escuela y alternativas sin tecnología para completar la tarea.","Pedir a las familias que consigan un dispositivo prestado.","Evaluar el uso de tecnología como criterio de nota, para que todos se esfuercen en conseguirla."]'::jsonb, 1, 'Inclusión digital.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('m-learning', 0, '¿Cuál es la principal ventaja del m-learning en contextos con acceso limitado a computadoras?', '["Los celulares son más baratos que los libros de texto","El celular es el dispositivo tecnológico más accesible en muchos hogares","Las apps educativas funcionan mejor en el celular que en cualquier computadora","El celular permite aplicar exámenes en línea a todo el grupo"]'::jsonb, 1, 'La clave es la accesibilidad: en muchos hogares hay celular, pero no computadora. El m-learning aprovecha el dispositivo que los estudiantes ya tienen, reduciendo la brecha tecnológica.', 'lesson'),
('m-learning', 1, '¿Qué característica define mejor al microaprendizaje en el m-learning?', '["Usar aplicaciones con inteligencia artificial","Sesiones de aprendizaje cortas e intencionadas de 5 a 15 minutos","Aprender sobre todo con videos animados","Repasar el contenido completo de una unidad en cada sesión de estudio"]'::jsonb, 1, 'El microaprendizaje se caracteriza por sesiones breves e intencionadas. No depende del tipo de contenido ni de la conectividad, sino de la estructura en pequeñas dosis que el cerebro puede procesar y retener mejor.', 'lesson'),
('m-learning', 2, '¿Cuál de estas apps es más adecuada para refuerzo de matemáticas sin conexión a internet?', '["Duolingo, porque tiene ejercicios offline de álgebra","Kolibri, porque permite descargar una vez lecciones (incluidas las de Khan Academy) y usarlas sin internet","WhatsApp, porque se pueden enviar ejercicios en PDF","YouTube, porque los videos se guardan automáticamente"]'::jsonb, 1, 'Kolibri está diseñada para funcionar sin conexión: se descargan los contenidos una vez (por ejemplo, lecciones de Khan Academy) y luego se usan sin internet. Duolingo es para idiomas, no matemáticas; un PDF por WhatsApp no da práctica con retroalimentación, y YouTube no guarda los videos automáticamente.', 'lesson'),
('m-learning', 3, 'Un docente quiere recibir tareas fotográficas de sus estudiantes sin gastar dinero. ¿Cuál es la opción más práctica en muchos contextos escolares de la región?', '["Crear una cuenta en Google Classroom para cada estudiante","Pedir que compartan fotos por WhatsApp al grupo de clase","Usar una plataforma de pago que exija crear una cuenta para cada estudiante","Solicitar que impriman las tareas y las entreguen el lunes"]'::jsonb, 1, 'WhatsApp es la herramienta más instalada y con menor barrera de entrada en muchos contextos de la región. Recibir fotos de tareas por WhatsApp es inmediato, gratuito y no requiere que los estudiantes creen cuentas nuevas.', 'lesson'),
('m-learning', 4, 'Según el modelo SAMR, ¿cuál actividad representa el nivel más alto de integración del celular?', '["Fotografiar las respuestas escritas del cuaderno y enviarlas al docente","Responder un cuestionario en Google Forms en lugar de en papel","Crear un podcast colaborativo para la comunidad","Buscar la definición de una palabra en un diccionario en línea"]'::jsonb, 2, 'Crear un podcast colaborativo para la comunidad es Redefinición: una tarea que no existiría sin la tecnología móvil. Las otras opciones son Sustitución (misma tarea, diferente formato) o Aumento (ligera mejora funcional).', 'lesson'),
('m-learning', 5, '¿Cuál es el principal beneficio de usar un formulario de ''salida de clase'' con el celular?', '["Permite calificar automáticamente a todos los estudiantes","Permite registrar la asistencia de forma rápida","Proporciona información en tiempo real sobre las dudas reales del grupo","Reemplaza las evaluaciones del periodo"]'::jsonb, 2, 'El valor de la salida de clase con formulario es la retroalimentación inmediata: el docente ve en tiempo real qué entendieron y qué no, y puede ajustar la siguiente clase basándose en datos reales, no suposiciones.', 'lesson'),
('m-learning', 6, '¿Cuál es la primera acción que debe tomar un docente antes de implementar m-learning en su aula?', '["Comprar tabletas para todos los estudiantes antes de planificar cualquier actividad","Solicitar wifi de alta velocidad al Ministerio de Educación","Hacer un diagnóstico de cuántos estudiantes tienen celular y con qué conectividad","Elegir la plataforma educativa más popular del mercado"]'::jsonb, 2, 'Siempre parte de la realidad de tus estudiantes. Un diagnóstico previo te permite diseñar actividades que funcionen para TODOS, no solo para los que tienen mejor tecnología. Sin ese diagnóstico, corres el riesgo de excluir a quienes más necesitan apoyo.', 'lesson'),
('m-learning', 7, '¿Qué estrategia de equidad digital es más efectiva cuando algunos estudiantes no tienen celular propio?', '["Excluirlos de las actividades de m-learning y darles a cambio trabajo extra en papel con el libro","Pedir a los padres que compren un celular básico para sus hijos","Diseñar actividades en pares donde un estudiante con celular colabora con uno sin","Posponer el m-learning hasta que todos tengan dispositivo"]'::jsonb, 2, 'El trabajo en pares es la estrategia más inclusiva e inmediata: permite que todos participen, fomenta la colaboración y no requiere recursos adicionales. Excluir o posponer viola el principio de equidad educativa.', 'lesson'),
('m-learning', 8, '¿Cuál de los siguientes indicadores es el más valioso para evaluar si el m-learning está funcionando en tu aula?', '["El número de apps instaladas en los celulares de los estudiantes","La velocidad de conexión a internet del aula","La mejora en comprensión y participación de los estudiantes","La cantidad de videos educativos disponibles en YouTube"]'::jsonb, 2, 'El éxito del m-learning se mide en aprendizaje, no en tecnología. La cantidad de apps o la velocidad de internet son medios, no fines. Lo que importa es si los estudiantes comprenden mejor y participan más activamente en su proceso educativo.', 'lesson'),
('m-learning', 9, 'En un grupo de 30 estudiantes, 24 tienen celular con datos, 4 comparten el de un familiar y 2 no tienen ninguno. La docente planea una actividad de investigación con el celular. ¿Qué diseño es más coherente con el enfoque de equidad del curso?', '["Hacer la actividad con quienes tienen celular y dar al resto una tarea equivalente en el libro.","Organizar parejas o equipos donde cada dispositivo sea compartido y ofrecer una versión en papel del mismo reto.","Pedir a las familias que presten un celular a los dos estudiantes que no tienen.","Posponer la actividad hasta que todos tengan un dispositivo propio, para que nadie quede en desventaja frente al resto."]'::jsonb, 1, 'La equidad digital exige diseñar para el celular compartido y ofrecer alternativa análoga. Excluir, penalizar o esperar amplía la brecha.', 'exam'),
('m-learning', 10, 'Una docente reemplaza la hoja de ejercicios de matemáticas por una foto de la misma hoja que los estudiantes responden en el celular. Según SAMR, ¿en qué nivel está y qué convendría hacer?', '["Redefinición; el celular transforma la tarea al hacerla digital.","Modificación; añadir más ejercicios para subir de nivel.","Sustitución; conviene rediseñarla, por ejemplo grabando la explicación del procedimiento.","Aumento; la foto agrega la ventaja de entregar más rápido."]'::jsonb, 2, 'Cambiar el soporte sin cambiar la tarea es Sustitución. Para subir de nivel, la tarea debe aprovechar lo que el celular permite, como grabar, colaborar o crear.', 'exam'),
('m-learning', 11, 'Un docente quiere elegir una app para que sus estudiantes practiquen vocabulario en casa con datos limitados. Una app es muy atractiva pero consume mucho dato y exige registro con correo. Otra es más sencilla, funciona sin conexión y no pide cuenta. ¿Qué decisión sigue los criterios del curso?', '["La más atractiva, porque la motivación es lo más importante.","La más sencilla, porque cumple los criterios de gratuidad, uso sin conexión y baja barrera de entrada.","La más atractiva, pero solo para quienes tengan wifi en casa.","Las dos, para que cada estudiante elija según su preferencia."]'::jsonb, 1, 'Los criterios del curso priorizan gratuidad, funcionamiento sin internet, poco consumo de datos y facilidad de acceso para no dejar a nadie fuera.', 'exam'),
('m-learning', 12, 'Después de un mes de m-learning, una docente quiere saber si funciona. Tiene tres datos: los estudiantes usan más el celular, completan más tareas y siguen cometiendo los mismos errores en las evaluaciones. ¿Qué conclusión es más adecuada?', '["Funciona, porque aumentó el uso del celular con fines escolares.","Funciona, porque hay más tareas completadas que antes.","Aún no hay evidencia suficiente de aprendizaje; debe revisar el diseño de las actividades y medir comprensión.","Funciona a medias; conviene sumar más actividades con celular para que mejoren."]'::jsonb, 2, 'El indicador valioso es la mejora de la comprensión y la participación, no el uso del dispositivo ni la cantidad de tareas. Hay que rediseñar y volver a medir.', 'exam'),
('m-learning', 13, 'Durante una actividad con celular, un estudiante usa el dispositivo para otra cosa y la docente le quita el celular delante de todos. ¿Qué habría prevenido mejor la situación según el curso?', '["Establecer desde el inicio que quien lo use para otra cosa lo pierde por el resto de la semana.","Construir con el grupo normas claras de uso: cuándo, para qué y qué pasa si no se cumplen.","Pedir que dejen los celulares sobre el escritorio del docente hasta que se necesiten.","Hacer actividades más largas para que no haya tiempo libre."]'::jsonb, 1, 'El éxito del m-learning depende de normas co-construidas y claras. Las normas consensuadas previenen el conflicto mejor que la prohibición o el control.', 'exam'),
('m-learning', 14, 'Una docente quiere que los estudiantes enseñen un concepto de ciencias a sus compañeros más pequeños usando solo el celular. ¿Qué actividad aprovecha mejor el nivel más alto de integración del celular?', '["Leer en el celular un resumen del tema y responder preguntas de opción múltiple sobre el texto leído.","Grabar un microvideo o podcast de 2 a 4 minutos explicando el concepto y compartirlo con otro grupo.","Fotografiar el cuaderno con la explicación.","Buscar el concepto en un buscador y copiar la definición."]'::jsonb, 1, 'Crear y compartir contenido nuevo (microvideo o podcast) corresponde a los niveles altos de SAMR y exige comprender para explicar.', 'exam'),
('m-learning', 15, '¿Qué es el aprendizaje ubicuo que hace posible el celular?', '["Aprender con el celular dentro del aula, con supervisión","Aprender en cualquier lugar: en el bus, en casa, esperando","Aprender en plataformas en línea desde una computadora","Aprender por cuenta propia, sin ninguna actividad del docente"]'::jsonb, 1, 'El celular permite que el aprendizaje ocurra fuera del horario y del espacio escolar, con actividades bien diseñadas por el docente.', 'exam'),
('m-learning', 16, '¿Cuál es la diferencia principal entre m-learning y e-learning?', '["El m-learning es más interactivo porque usa pantallas táctiles","El e-learning suele exigir computadora y buena conexión; el m-learning funciona desde el celular","El e-learning es formal y el m-learning es informal","El m-learning se usa sobre todo para idiomas y repasos"]'::jsonb, 1, 'El m-learning aprovecha el dispositivo más accesible en muchos hogares y se adapta a ratos cortos.', 'exam'),
('m-learning', 17, 'En el m-learning, ¿cuál es el rol principal del docente?', '["Transmisor: enviar el contenido al celular para que cada uno lo estudie","Curador y guía: elegir buenas apps, diseñar actividades y acompañar","Supervisor: controlar el tiempo de pantalla de cada estudiante","Productor: grabar todos los videos que verán los estudiantes"]'::jsonb, 1, 'El docente selecciona recursos, diseña actividades con propósito y orienta el uso del celular.', 'exam'),
('m-learning', 18, '¿Qué tipo de m-learning es buscar por cuenta propia un video en YouTube sobre un tema que interesa?', '["Formal (asignado)","Informal","No formal","Formal autodirigido"]'::jsonb, 1, 'El m-learning formal lo asigna el docente; el informal ocurre por iniciativa propia. Ambos pueden aprovecharse.', 'exam'),
('m-learning', 19, '¿Qué criterio NO aparece entre los recomendados para elegir una app educativa?', '["Que sea gratuita o tenga una versión gratuita suficiente","Que funcione con pocos datos o sin conexión","Que sea la más popular en redes sociales","Que sea fácil de usar para los estudiantes"]'::jsonb, 2, 'La popularidad no es un criterio pedagógico. Importan el costo, la conectividad, la facilidad y el propósito.', 'exam'),
('m-learning', 20, 'Los estudiantes graban un podcast explicando un tema de ciencias para la comunidad. ¿Qué ventaja destaca el curso?', '["Que el celular sirve también para crear, no solo para consumir contenido","Que reemplaza la evaluación escrita del tema","Que no requiere planificación previa del docente","Que mejora la expresión oral, más allá del contenido científico"]'::jsonb, 0, 'Crear contenido (audio, video) exige comprender y explicar, lo que profundiza el aprendizaje.', 'exam'),
('m-learning', 21, '¿Cómo se organiza una cacería de pistas con el celular?', '["Los estudiantes reciben pistas (por ejemplo, por WhatsApp) y buscan respuestas investigando y moviéndose","Los estudiantes responden en orden una lista de preguntas proyectada en la pizarra","Cada estudiante responde un examen en línea en silencio","Cada equipo busca en internet las respuestas a un cuestionario sin salir del aula"]'::jsonb, 0, 'Combina movimiento, investigación y tecnología con un propósito claro.', 'exam'),
('m-learning', 22, '¿Qué preguntas responde la plantilla de actividad móvil del curso?', '["Qué app usar, cuántos datos consume y si es gratuita","Qué aprenderán, qué harán con el celular, cuánto tiempo tendrán y cómo se evaluará","Quién tiene celular, quién no y cómo agruparlos","Qué normas de uso se aplican y qué pasa si no se cumplen"]'::jsonb, 1, 'Objetivo, tarea, tiempo y evaluación aseguran que el celular tenga un propósito pedagógico.', 'exam'),
('m-learning', 23, 'Además de usar el celular para aprender, ¿qué oportunidad abre integrarlo al aula?', '["Enseñar ciudadanía digital: verificar fuentes, proteger datos y convivir con respeto en línea","Comunicarse con los estudiantes fuera del horario de clase","Usar las redes sociales de los estudiantes para publicar sus trabajos","Reducir el uso de papel y fotocopias en la escuela"]'::jsonb, 0, 'Usar el celular con guía es la ocasión para enseñar a usarlo bien.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('flipped-classroom', 0, '¿Cuál es la característica principal que diferencia el aula invertida de la clase tradicional?', '["En el aula invertida no hay tareas para casa","El docente explica los conceptos nuevos mediante videos que los estudiantes ven antes de clase","Los estudiantes enseñan la clase en lugar del docente","Las evaluaciones se hacen en casa y la explicación en clase"]'::jsonb, 1, 'La inversión clave es dónde ocurre la instrucción directa: en el aula invertida, los estudiantes acceden al contenido nuevo (generalmente en video) ANTES de clase, y el tiempo presencial se dedica a práctica, discusión y proyectos con el docente disponible.', 'lesson'),
('flipped-classroom', 1, 'Según la taxonomía de Bloom aplicada al flipped classroom, ¿qué tipos de actividades se diseñan para el tiempo presencial en clase?', '["Recordar y comprender: copiar definiciones y memorizar fórmulas","Aplicar: resolver ejercicios iguales a los del video, de forma individual y en silencio","Analizar, evaluar y crear: debatir, resolver problemas complejos, crear proyectos","Ver el video nuevamente en grupo para verificar que todos lo entendieron"]'::jsonb, 2, 'El tiempo presencial en el aula invertida se reserva para los niveles cognitivos altos de Bloom: analizar, evaluar y crear. Los niveles básicos (recordar y comprender) se trabajan con el video en casa. Así el docente guía cuando más se necesita.', 'lesson'),
('flipped-classroom', 2, '¿Cuál es la duración óptima recomendada para un video de aula invertida?', '["30 a 45 minutos, equivalente a un período de clase completo","Menos de 2 minutos para mantener la atención","Entre 6 y 10 minutos, con una sola idea central","Más de 20 minutos para cubrir el tema con profundidad"]'::jsonb, 2, 'Los estudios muestran que el engagement baja drásticamente después de 6 minutos. Entre 6 y 10 minutos es el rango óptimo: suficiente para explicar con profundidad, corto para mantener la atención. Si el tema es largo, divídelo en varios videos cortos.', 'lesson'),
('flipped-classroom', 3, '¿Qué aspecto técnico tiene mayor impacto en la calidad de un video educativo según los expertos?', '["La resolución de imagen (Full HD vs. 4K)","Los efectos de transición y las animaciones en las diapositivas","La claridad del audio: que la voz se escuche limpia y sin eco","El fondo del video (debe ser un fondo liso y profesional)"]'::jsonb, 2, 'El audio es el elemento más crítico de un video educativo. Los estudiantes pueden aprender con imagen de menor calidad, pero un audio malo (eco, ruido, voz baja) hace que abandonen el video inmediatamente. Prioriza el sonido sobre cualquier otro aspecto técnico.', 'lesson'),
('flipped-classroom', 4, '¿Para qué sirve la ''entrada de clase'' en el aula invertida?', '["Para asignar una nota de participación a quienes vieron el video","Para repetir la explicación del video a quienes no lo vieron","Para verificar la comprensión del video e identificar dudas comunes antes de la actividad","Para que los estudiantes copien notas del video en su cuaderno"]'::jsonb, 2, 'La entrada de clase es diagnóstica, no punitiva. Su función es que el docente sepa qué entendieron, qué no, y cuáles son las dudas más frecuentes, para organizar mejor el tiempo de clase. No se usa para castigar a quienes no vieron el video.', 'lesson'),
('flipped-classroom', 5, '¿Cuál de estas actividades es la más adecuada para el tiempo presencial en el aula invertida?', '["El docente explica el tema desde el inicio sin mencionar el video","Los estudiantes ven el video en clase porque no tienen internet en casa","Equipos de estudiantes resuelven problemas complejos mientras el docente circula y apoya","Los estudiantes copian en su cuaderno los puntos clave del video mientras el docente revisa tareas"]'::jsonb, 2, 'El tiempo presencial debe usarse para actividades que requieren la presencia del docente y la colaboración entre pares: resolver problemas, debatir, crear. Repetir la explicación o copiar notas desperdicia el tiempo más valioso del día de clase.', 'lesson'),
('flipped-classroom', 6, '¿Cuál es la estrategia más efectiva para un estudiante sin internet en casa que necesita ver el video del aula invertida?', '["Pedirle que no participe en la actividad de clase hasta que vea el video","Repetir la explicación del video en clase para que no se pierda nada","Enviar el video por WhatsApp para que se descargue en la escuela y lo vea sin internet","Darle una tarea alternativa del libro para que trabaje mientras el grupo hace la actividad"]'::jsonb, 2, 'Enviar el video por WhatsApp permite descargarlo con wifi escolar y verlo sin internet en casa. Esta solución es simple, gratuita y respeta la dignidad del estudiante sin excluirlo ni penalizarlo por su situación de conectividad.', 'lesson'),
('flipped-classroom', 7, 'Un docente nuevo en aula invertida no tiene tiempo de grabar todos sus videos. ¿Cuál es la recomendación más práctica?', '["Posponer el método hasta tener tiempo de grabar todos los videos","Curar videos existentes para lo básico y grabar solo los temas difíciles","Grabar un solo video largo que cubra todo el tema y reutilizarlo cada año","Pedir a los estudiantes que busquen sus propios videos sin orientación"]'::jsonb, 1, 'La curaduría de videos existentes (YouTube, Khan Academy) es perfectamente válida y sostenible. El valor del docente no está en ser actor de video sino en seleccionar el mejor contenido y diseñar las actividades presenciales. Grabar solo donde se agrega valor único es la estrategia más eficiente.', 'lesson'),
('flipped-classroom', 8, '¿Cuál es la señal más clara de que el aula invertida está funcionando en tu grupo?', '["Los estudiantes memorizan perfectamente el contenido del video de cada semana","Todos los estudiantes ven el video completo antes de clase","Llegan con preguntas específicas y la clase presencial es más activa","Las notas del examen suben desde la primera semana"]'::jsonb, 2, 'La señal más valiosa del aula invertida exitosa es que los estudiantes llegan con preguntas específicas (indicio de que vieron y procesaron el video) y que el tiempo de clase es activo y colaborativo. Eso significa que la inversión está funcionando: el conocimiento entra antes y la clase se usa para profundizar.', 'lesson'),
('flipped-classroom', 9, 'Una docente graba un video de 25 minutos con todo el tema del mes para que lo vean en casa. En clase, la mayoría dice que no lo terminó. ¿Qué ajuste recomienda el curso?', '["Mostrar el video completo en clase para asegurar que todos lo vean.","Dividir el contenido en videos de 6 a 10 minutos con una sola idea central cada uno.","Pedir que lo vean dos veces en casa y tomen notas.","Dar una nota por haberlo visto completo para motivarlos."]'::jsonb, 1, 'La duración efectiva de los videos educativos es de 6 a 10 minutos con una sola idea. Videos largos reducen el compromiso.', 'exam'),
('flipped-classroom', 10, 'Al iniciar la clase invertida, 8 de 30 estudiantes no vieron el video. La docente empieza a explicar todo de nuevo para que nadie quede atrás. ¿Qué consecuencia pedagógica tiene esa decisión?', '["Ninguna; repetir la explicación asegura que todos partan igual.","Anula la ventaja del método, porque se pierde el tiempo de clase para actividades de nivel alto y se premia no ver el video.","Mejora la comprensión, porque el grupo escucha el tema dos veces.","Aumenta la autonomía del grupo."]'::jsonb, 1, 'Repetir la explicación desperdicia el tiempo ganado y desincentiva ver el video. Conviene ofrecer una alternativa breve a quienes no lo vieron y avanzar con la actividad.', 'exam'),
('flipped-classroom', 11, 'Un docente quiere comprobar rápidamente si los estudiantes vieron y entendieron el video antes de la actividad. Tiene 5 minutos. ¿Qué estrategia es la más adecuada?', '["Un examen escrito de 20 preguntas sobre todo el video, calificado y sumado a la nota final del periodo.","Una entrada de clase de 2 o 3 preguntas rápidas que revele quién lo vio y cuáles son las dudas comunes.","Pedir que levanten la mano quienes lo vieron.","Calificar un resumen entregado en casa."]'::jsonb, 1, 'La entrada de clase es breve, diagnóstica y orienta la actividad; no necesita ser una calificación pesada.', 'exam'),
('flipped-classroom', 12, 'Una maestra no tiene tiempo para grabar todos sus videos. Tiene un tema difícil que quiere explicar con su propia voz y varios temas básicos que ya explican bien otros canales confiables. ¿Cuál es la estrategia más realista?', '["Grabar todo ella misma, aunque tarde meses.","Usar videos de otros canales para todos los temas, aunque no se ajusten a su grupo.","Curar videos confiables para los temas básicos y grabar solo los temas difíciles o muy contextualizados.","Esperar a tener tiempo y un lugar adecuado para grabar."]'::jsonb, 2, 'Curar y grabar de forma selectiva ahorra tiempo y mantiene la pertinencia. El método no exige producir todo el contenido.', 'exam'),
('flipped-classroom', 13, 'Un director dice: ''¿El maestro ya no da clase si los alumnos ven videos en casa?''. ¿Cuál es la mejor respuesta del docente?', '["Responder que el docente sigue dando clase, pero ahora la graba para verla en casa.","Explicar que el video transmite la información básica y que el tiempo de clase se usa para practicar, resolver dudas y acompañar de cerca a cada estudiante.","Invitarlo a ver uno de los videos para que compruebe su calidad.","Prometer que volverá a explicar todo en clase."]'::jsonb, 1, 'El rol del docente se transforma de expositor a facilitador. Comunicar el propósito con claridad reduce la resistencia.', 'exam'),
('flipped-classroom', 14, 'Una docente de matemáticas tiene 45 minutos. Ya ha dado el video para casa. ¿Qué distribución del tiempo es más coherente con el curso?', '["40 minutos de explicación y 5 de práctica.","5 min de entrada, 5 de dudas, unos 30 de trabajo en equipos y 5 de cierre.","20 minutos de repaso del video, 20 de ejercicios individuales en silencio y 5 minutos de cierre.","15 minutos de explicación de refuerzo y 30 de trabajo en equipos."]'::jsonb, 1, 'La estructura sugerida prioriza la actividad práctica y colaborativa, con entrada breve y cierre.', 'exam'),
('flipped-classroom', 15, '¿Quiénes popularizaron el aula invertida y cómo empezó?', '["Dos profesores de química, Bergmann y Sams, que grababan sus clases para estudiantes que faltaban","Un ministerio de educación con una reforma nacional","Una empresa de tecnología que vendía tabletas","Una universidad que grababa clases magistrales para sus cursos a distancia"]'::jsonb, 0, 'Jonathan Bergmann y Aaron Sams empezaron hacia 2007 grabando lecciones para quienes no podían asistir.', 'exam'),
('flipped-classroom', 16, '¿En qué tipo de materias o temas funciona especialmente bien el aula invertida?', '["En temas con mucha instrucción directa, como matemáticas, ciencias o gramática","En educación física y artes, donde hay más práctica","En temas que los estudiantes ya conocen bien, para repasar","En temas de debate y opinión, donde no hay respuestas correctas"]'::jsonb, 0, 'Cuando hay mucha explicación, trasladarla al video libera tiempo de clase para practicar con apoyo.', 'exam'),
('flipped-classroom', 17, 'Para tu primer ''flip'', ¿qué tema conviene elegir?', '["Uno que ya explicas bien","El tema más nuevo y difícil para ti","Uno que los estudiantes ya dominan","El tema de más peso en el examen final"]'::jsonb, 0, 'Empezar con algo que dominas reduce la carga y permite enfocarte en la nueva forma de trabajar.', 'exam'),
('flipped-classroom', 18, '¿Cómo se comparte un video de YouTube para que solo lo vea quien tiene el enlace?', '["Publicándolo como ''no listado''","Publicándolo como ''público'' con muchas etiquetas","Subiéndolo a una lista de reproducción pública de la escuela","Publicándolo como ''privado'', así cualquiera con el enlace lo ve"]'::jsonb, 0, 'La opción ''no listado'' evita que el video aparezca en búsquedas, útil para material de clase.', 'exam'),
('flipped-classroom', 19, '¿Qué hace más poderoso un video de aula invertida, además de explicar?', '["Música de fondo durante todo el video","Preguntas integradas que piden pausar y pensar","Una presentación con todo el texto en pantalla","Mostrar al docente en primer plano todo el tiempo"]'::jsonb, 1, 'Pedir ''pausa aquí y escribe tu respuesta'' convierte al estudiante en participante activo.', 'exam'),
('flipped-classroom', 20, '¿Cómo funciona el debate socrático en el tiempo presencial?', '["El docente expone su postura y los estudiantes la discuten","El docente solo hace preguntas y los estudiantes defienden y revisan sus ideas","Los estudiantes leen un texto y responden preguntas por escrito","Dos equipos debaten y el docente decide quién ganó"]'::jsonb, 1, 'Las preguntas del docente obligan a argumentar y profundizar lo visto en el video.', 'exam'),
('flipped-classroom', 21, 'Mientras el grupo trabaja, la docente se sienta con tres estudiantes que tienen la misma duda. ¿Qué ventaja del aula invertida aprovecha?', '["Que el docente ya no necesita planificar","Que el tiempo de clase liberado permite atender la diversidad en pequeños grupos","Que los estudiantes avanzados pueden explicar a los demás sin necesidad del docente","Que se puede evaluar más rápido con examen escrito"]'::jsonb, 1, 'Con la explicación en el video, el docente tiene tiempo para apoyar a quien más lo necesita.', 'exam'),
('flipped-classroom', 22, '¿Cómo es la evaluación en el aula invertida, según el curso?', '["Un único examen al final del periodo","Continua y diversa: entrada de clase, observación durante las actividades y productos","Basada en las estadísticas de reproducción del video","Basada en la participación durante la clase presencial"]'::jsonb, 1, 'La evaluación acompaña cada momento: diagnóstica, formativa y sumativa.', 'exam'),
('flipped-classroom', 23, '¿Qué plan de implementación propone el curso?', '["Invertir todas las materias desde el primer día de clases","Gradual: una lección, luego una unidad, y después ampliar","Esperar a tener todos los videos grabados del año","Probarlo durante todo un periodo con una sola materia antes de decidir"]'::jsonb, 1, 'Escalar de a poco permite aprender del proceso y ajustar sin agotarse.', 'exam')
